46	int AsyncInfoTy::synchronize() {
47	  int Result = OFFLOAD_SUCCESS;
48	  if (!isQueueEmpty()) {
49	    switch (SyncType) {
50	    case SyncTy::BLOCKING:
51	      // If we have a queue we need to synchronize it now.
52	      Result = Device.synchronize(*this);
53	      assert(AsyncInfo.Queue == nullptr &&
54	             "The device plugin should have nulled the queue to indicate there "
55	             "are no outstanding actions!");
56	      break;
57	    case SyncTy::NON_BLOCKING:
58	      Result = Device.queryAsync(*this);
59	      break;
60	    }
61	  }
62	
63	  // Run any pending post-processing function registered on this async object.
64	  if (Result == OFFLOAD_SUCCESS && isQueueEmpty()) {
65	    ODBG(ODT_DataTransfer)
66	        << "Synchronization complete, running post-processing";
67	    Result = runPostProcessing();
68	  }
69	
70	  return Result;
71	}
