80	int32_t AsyncInfoTy::runPostProcessing() {
81	  size_t Size = PostProcessingFunctions.size();
82	  for (size_t I = 0; I < Size; ++I) {
83	    const int Result = PostProcessingFunctions[I]();
84	    if (Result != OFFLOAD_SUCCESS)
85	      return Result;
86	  }
87	
88	  // Clear the vector up until the last known function, since post-processing
89	  // procedures might add new procedures themselves.
90	  const auto *PrevBegin = PostProcessingFunctions.begin();
91	  PostProcessingFunctions.erase(PrevBegin, PrevBegin + Size);
92	
93	  return OFFLOAD_SUCCESS;
94	}
