98	/* All begin addresses for partially mapped structs must be aligned, up to 16,
99	 * in order to ensure proper alignment of members. E.g.
100	 *
101	 * struct S {
102	 *   int a;   // 4-aligned
103	 *   int b;   // 4-aligned
104	 *   int *p;  // 8-aligned
105	 * } s1;
106	 * ...
107	 * #pragma omp target map(tofrom: s1.b, s1.p[0:N])
108	 * {
109	 *   s1.b = 5;
110	 *   for (int i...) s1.p[i] = ...;
111	 * }
112	 *
113	 * Here we are mapping s1 starting from member b, so BaseAddress=&s1=&s1.a and
114	 * BeginAddress=&s1.b. Let's assume that the struct begins at address 0x100,
115	 * then &s1.a=0x100, &s1.b=0x104, &s1.p=0x108. Each member obeys the alignment
116	 * requirements for its type. Now, when we allocate memory on the device, in
117	 * CUDA's case cuMemAlloc() returns an address which is at least 256-aligned.
118	 * This means that the chunk of the struct on the device will start at a
119	 * 256-aligned address, let's say 0x200. Then the address of b will be 0x200 and
120	 * address of p will be a misaligned 0x204 (on the host there was no need to add
121	 * padding between b and p, so p comes exactly 4 bytes after b). If the device
122	 * kernel tries to access s1.p, a misaligned address error occurs (as reported
123	 * by the CUDA plugin). By padding the begin address down to a multiple of 8 and
124	 * extending the size of the allocated chuck accordingly, the chuck on the
125	 * device will start at 0x200 with the padding (4 bytes), then &s1.b=0x204 and
126	 * &s1.p=0x208, as they should be to satisfy the alignment requirements.
127	 */
128	static const int64_t MaxAlignment = 16;
129	
130	/// Return the alignment requirement of partially mapped structs, see
131	/// MaxAlignment above.
132	static uint64_t getPartialStructRequiredAlignment(void *HstPtrBase) {
133	  int LowestOneBit = __builtin_ffsl(reinterpret_cast<uintptr_t>(HstPtrBase));
134	  uint64_t BaseAlignment = 1 << (LowestOneBit - 1);
135	  return MaxAlignment < BaseAlignment ? MaxAlignment : BaseAlignment;
136	}
