138	void handleTargetOutcome(bool Success, ident_t *Loc) {
139	  switch (OffloadPolicy::get(*PM).Kind) {
140	  case OffloadPolicy::DISABLED:
141	    if (Success) {
142	      FATAL_MESSAGE0(1, "expected no offloading while offloading is disabled");
143	    }
144	    break;
145	  case OffloadPolicy::MANDATORY:
146	    if (!Success) {
147	      if (getInfoLevel() & OMP_INFOTYPE_DUMP_TABLE) {
148	        auto ExclusiveDevicesAccessor = PM->getExclusiveDevicesAccessor();
149	        for (auto &Device : PM->devices(ExclusiveDevicesAccessor))
150	          dumpTargetPointerMappings(Loc, Device);
151	      } else
152	        FAILURE_MESSAGE("Consult https://openmp.llvm.org/design/Runtimes.html "
153	                        "for debugging options.\n");
154	
155	      if (!PM->getNumActivePlugins()) {
156	        FAILURE_MESSAGE(
157	            "No images found compatible with the installed hardware. ");
158	
159	        llvm::SmallVector<llvm::StringRef> Archs;
160	        for (auto &Image : PM->deviceImages()) {
161	          const char *Start = reinterpret_cast<const char *>(
162	              Image.getExecutableImage().ImageStart);
163	          uint64_t Length =
164	              utils::getPtrDiff(Start, Image.getExecutableImage().ImageEnd);
165	          llvm::MemoryBufferRef Buffer(llvm::StringRef(Start, Length),
166	                                       /*Identifier=*/"");
167	
168	          auto ObjectOrErr = llvm::object::ObjectFile::createObjectFile(Buffer);
169	          if (auto Err = ObjectOrErr.takeError()) {
170	            llvm::consumeError(std::move(Err));
171	            continue;
172	          }
173	
174	          if (auto CPU = (*ObjectOrErr)->tryGetCPUName())
175	            Archs.push_back(*CPU);
176	        }
177	        fprintf(stderr, "Found %zu image(s): (%s)\n", Archs.size(),
178	                llvm::join(Archs, ",").c_str());
179	      }
180	
181	      SourceInfo Info(Loc);
182	      if (Info.isAvailible())
183	        fprintf(stderr, "%s:%d:%d: ", Info.getFilename(), Info.getLine(),
184	                Info.getColumn());
185	      else
186	        FAILURE_MESSAGE("Source location information not present. Compile with "
187	                        "-g or -gline-tables-only.\n");
188	      FATAL_MESSAGE0(
189	          1, "failure of target construct while offloading is mandatory");
190	    } else {
191	      if (getInfoLevel() & OMP_INFOTYPE_DUMP_TABLE) {
192	        auto ExclusiveDevicesAccessor = PM->getExclusiveDevicesAccessor();
193	        for (auto &Device : PM->devices(ExclusiveDevicesAccessor))
194	          dumpTargetPointerMappings(Loc, Device);
195	      }
196	    }
197	    break;
198	  }
199	}
