205	void *targetAllocExplicit(size_t Size, int DeviceNum, int Kind,
206	                          const char *Name) {
207	  ODBG(ODT_Interface) << "Call to " << Name << " for device " << DeviceNum
208	                      << " requesting " << Size << " bytes";
209	
210	  if (Size <= 0) {
211	    ODBG(ODT_Interface) << "Call to " << Name << " with non-positive length";
212	    return NULL;
213	  }
214	
215	  void *Rc = NULL;
216	
217	  if (isInitialDevice(DeviceNum)) {
218	    Rc = malloc(Size);
219	    ODBG(ODT_Interface) << Name << " returns host ptr " << Rc;
220	    return Rc;
221	  }
222	
223	  auto DeviceOrErr = PM->getDevice(DeviceNum);
224	  if (!DeviceOrErr)
225	    FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
226	
227	  Rc = DeviceOrErr->allocData(Size, nullptr, Kind);
228	  ODBG(ODT_Interface) << Name << " returns device ptr " << Rc;
229	  return Rc;
230	}
