232	void targetFreeExplicit(void *DevicePtr, int DeviceNum, int Kind,
233	                        const char *Name) {
234	  ODBG(ODT_Interface) << "Call to " << Name << " for device " << DeviceNum
235	                      << " and address " << DevicePtr;
236	
237	  if (!DevicePtr) {
238	    ODBG(ODT_Interface) << "Call to " << Name << " with NULL ptr";
239	    return;
240	  }
241	
242	  if (isInitialDevice(DeviceNum)) {
243	    free(DevicePtr);
244	    ODBG(ODT_Interface) << Name << " deallocated host ptr";
245	    return;
246	  }
247	
248	  auto DeviceOrErr = PM->getDevice(DeviceNum);
249	  if (!DeviceOrErr)
250	    FATAL_MESSAGE(DeviceNum, "%s", toString(DeviceOrErr.takeError()).c_str());
251	
252	  if (DeviceOrErr->deleteData(DevicePtr, Kind) == OFFLOAD_FAIL)
253	    FATAL_MESSAGE(DeviceNum, "%s",
254	                  "Failed to deallocate device ptr. Set "
255	                  "OFFLOAD_TRACK_ALLOCATION_TRACES=1 to track allocations.");
256	
257	  ODBG(ODT_Interface) << "omp_target_free deallocated device ptr";
258	}
