298	/// Call the user-defined mapper function followed by the appropriate
299	// targetData* function (targetData{Begin,End,Update}).
300	int targetDataMapper(ident_t *Loc, DeviceTy &Device, void *ArgBase, void *Arg,
301	                     int64_t ArgSize, int64_t ArgType, map_var_info_t ArgNames,
302	                     void *ArgMapper, AsyncInfoTy &AsyncInfo,
303	                     TargetDataFuncPtrTy TargetDataFunction,
304	                     StateInfoTy *StateInfo = nullptr) {
305	  ODBG(ODT_Interface) << "Calling the mapper function " << ArgMapper;
306	
307	  // The mapper function fills up Components.
308	  MapperComponentsTy MapperComponents;
309	  MapperFuncPtrTy MapperFuncPtr = (MapperFuncPtrTy)(ArgMapper);
310	  (*MapperFuncPtr)((void *)&MapperComponents, ArgBase, Arg, ArgSize, ArgType,
311	                   ArgNames);
312	
313	  // Construct new arrays for args_base, args, arg_sizes and arg_types
314	  // using the information in MapperComponents and call the corresponding
315	  // targetData* function using these new arrays.
316	  SmallVector<void *> MapperArgsBase(MapperComponents.Components.size());
317	  SmallVector<void *> MapperArgs(MapperComponents.Components.size());
318	  SmallVector<int64_t> MapperArgSizes(MapperComponents.Components.size());
319	  SmallVector<int64_t> MapperArgTypes(MapperComponents.Components.size());
320	  SmallVector<void *> MapperArgNames(MapperComponents.Components.size());
321	
322	  for (unsigned I = 0, E = MapperComponents.Components.size(); I < E; ++I) {
323	    auto &C = MapperComponents.Components[I];
324	    MapperArgsBase[I] = C.Base;
325	    MapperArgs[I] = C.Begin;
326	    MapperArgSizes[I] = C.Size;
327	    MapperArgTypes[I] = C.Type;
328	    MapperArgNames[I] = C.Name;
329	  }
330	
331	  int Rc = TargetDataFunction(Loc, Device, MapperComponents.Components.size(),
332	                              MapperArgsBase.data(), MapperArgs.data(),
333	                              MapperArgSizes.data(), MapperArgTypes.data(),
334	                              MapperArgNames.data(), /*arg_mappers*/ nullptr,
335	                              AsyncInfo, StateInfo, /*FromMapper=*/true);
336	
337	  return Rc;
338	}
