340	/// Returns a buffer of the requested \p Size, to be used as the source for
341	/// `submitData`.
342	///
343	/// For small buffers (`Size <= sizeof(void*)`), uses \p AsyncInfo's
344	/// getVoidPtrLocation().
345	/// For larger buffers, creates a dynamic buffer which will be eventually
346	/// deleted by \p AsyncInfo's post-processing callback.
347	static char *getOrCreateSourceBufferForSubmitData(AsyncInfoTy &AsyncInfo,
348	                                                  int64_t Size) {
349	  constexpr int64_t VoidPtrSize = sizeof(void *);
350	
351	  if (Size <= VoidPtrSize) {
352	    void *&BufferElement = AsyncInfo.getVoidPtrLocation();
353	    return reinterpret_cast<char *>(&BufferElement);
354	  }
355	
356	  // Create a dynamic buffer for larger data and schedule its deletion.
357	  char *DataBuffer = new char[Size];
358	  AsyncInfo.addPostProcessingFunction([DataBuffer]() {
359	    ODBG(ODT_DataTransfer) << "Releasing submitData source buffer at "
360	                           << static_cast<void *>(DataBuffer);
361	    delete[] DataBuffer;
362	    return OFFLOAD_SUCCESS;
363	  });
364	  return DataBuffer;
365	}
