367	/// Calculates the target pointee base by applying the host
368	/// pointee begin/base delta to the target pointee begin.
369	///
370	/// ```
371	/// TgtPteeBase = TgtPteeBegin - (HstPteeBegin - HstPteeBase)
372	/// ```
373	static void *calculateTargetPointeeBase(void *HstPteeBase, void *HstPteeBegin,
374	                                        void *TgtPteeBegin) {
375	  uint64_t Delta = reinterpret_cast<uint64_t>(HstPteeBegin) -
376	                   reinterpret_cast<uint64_t>(HstPteeBase);
377	  void *TgtPteeBase = reinterpret_cast<void *>(
378	      reinterpret_cast<uint64_t>(TgtPteeBegin) - Delta);
379	
380	  ODBG(ODT_Mapping) << "HstPteeBase: " << HstPteeBase
381	                    << ", HstPteeBegin: " << HstPteeBegin
382	                    << ", Delta (HstPteeBegin - HstPteeBase): " << Delta << "\n"
383	                    << "TgtPteeBase (TgtPteeBegin - Delta): " << TgtPteeBase
384	                    << ", TgtPteeBegin: " << TgtPteeBegin;
385	
386	  return TgtPteeBase;
387	}
