389	/// Utility function to perform a pointer attachment operation.
390	///
391	/// For something like:
392	/// ```cpp
393	///  int *p;
394	///  ...
395	///  #pragma omp target enter data map(to:p[10:10])
396	/// ```
397	///
398	/// for which the attachment operation gets represented using:
399	/// ```
400	///   &p, &p[10], sizeof(p), ATTACH
401	/// ```
402	///
403	/// (Hst|Tgt)PtrAddr   represents &p
404	/// (Hst|Tgt)PteeBase  represents &p[0]
405	/// (Hst|Tgt)PteeBegin represents &p[10]
406	///
407	/// This function first computes the expected TgtPteeBase using:
408	///   `<Select>TgtPteeBase = TgtPteeBegin - (HstPteeBegin - HstPteeBase)`
409	///
410	/// and then attaches TgtPteeBase to TgtPtrAddr.
411	///
412	/// \p HstPtrSize represents the size of the pointer p. For C/C++, this
413	/// should be same as "sizeof(void*)" (say 8).
414	///
415	/// However, for Fortran, pointers/allocatables, which are also eligible for
416	/// "pointer-attachment", may be implemented using descriptors that contain the
417	/// address of the pointee in the first 8 bytes, but also contain other
418	/// information such as lower-bound/upper-bound etc in their subsequent fields.
419	///
420	/// For example, for the following:
421	/// ```fortran
422	///   integer, allocatable :: x(:)
423	///   integer, pointer :: p(:)
424	///   ...
425	///   p => x(10: 19)
426	///   ...
427	///   !$omp target enter data map(to:p(:))
428	/// ```
429	///
430	/// The map should trigger a pointer-attachment (assuming the pointer-attachment
431	/// conditions as noted on processAttachEntries are met) between the descriptor
432	/// for p, and its pointee data.
433	///
434	/// Since only the first 8 bytes of the descriptor contain the address of the
435	/// pointee, an attachment operation on device descriptors involves:
436	/// * Setting the first 8 bytes of the device descriptor to point the device
437	/// address of the pointee.
438	/// * Copying the remaining information about bounds/offset etc. from the host
439	/// descriptor to the device descriptor.
440	///
441	/// The function also handles pointer-attachment portion of PTR_AND_OBJ maps,
442	/// like:
443	/// ```
444	///   &p, &p[10], 10 * sizeof(p[10]), PTR_AND_OBJ
445	/// ```
446	/// by using `sizeof(void*)` as \p HstPtrSize.
447	static int performPointerAttachment(DeviceTy &Device, AsyncInfoTy &AsyncInfo,
448	                                    void **HstPtrAddr, void *HstPteeBase,
449	                                    void *HstPteeBegin, void **TgtPtrAddr,
450	                                    void *TgtPteeBegin, int64_t HstPtrSize,
451	                                    TargetPointerResultTy &PtrTPR) {
452	  assert(PtrTPR.getEntry() &&
453	         "Need a valid pointer entry to perform pointer-attachment");
454	
455	  constexpr int64_t VoidPtrSize = sizeof(void *);
456	  assert(HstPtrSize >= VoidPtrSize && "PointerSize is too small");
457	
458	  void *TgtPteeBase =
459	      calculateTargetPointeeBase(HstPteeBase, HstPteeBegin, TgtPteeBegin);
460	
461	  // Add shadow pointer tracking
462	  if (!PtrTPR.getEntry()->addShadowPointer(
463	          ShadowPtrInfoTy{HstPtrAddr, TgtPtrAddr, TgtPteeBase, HstPtrSize})) {
464	    ODBG(ODT_Mapping) << "Pointer " << TgtPtrAddr << " is already attached to "
465	                      << TgtPteeBase;
466	    return OFFLOAD_SUCCESS;
467	  }
468	
469	  ODBG(ODT_Mapping) << "Update pointer (" << TgtPtrAddr << ") -> ["
470	                    << TgtPteeBase << "]\n";
471	
472	  // Lambda to handle submitData result and perform final steps.
473	  auto HandleSubmitResult = [&](int SubmitResult) -> int {
474	    if (SubmitResult != OFFLOAD_SUCCESS) {
475	      REPORT() << "Failed to update pointer on device.";
476	      return OFFLOAD_FAIL;
477	    }
478	
479	    if (PtrTPR.getEntry()->addEventIfNecessary(Device, AsyncInfo) !=
480	        OFFLOAD_SUCCESS)
481	      return OFFLOAD_FAIL;
482	
483	    return OFFLOAD_SUCCESS;
484	  };
485	
486	  // Get a buffer to be used as the source for data submission.
487	  char *SrcBuffer = getOrCreateSourceBufferForSubmitData(AsyncInfo, HstPtrSize);
488	
489	  // The pointee's address should occupy the first VoidPtrSize bytes
490	  // irrespective of HstPtrSize.
491	  std::memcpy(SrcBuffer, &TgtPteeBase, VoidPtrSize);
492	
493	  // For larger "pointers" (e.g., Fortran descriptors), copy remaining
494	  // descriptor fields from the host descriptor into the buffer.
495	  if (HstPtrSize > VoidPtrSize) {
496	    uint64_t HstDescriptorFieldsSize = HstPtrSize - VoidPtrSize;
497	    void *HstDescriptorFieldsAddr =
498	        reinterpret_cast<char *>(HstPtrAddr) + VoidPtrSize;
499	    std::memcpy(SrcBuffer + VoidPtrSize, HstDescriptorFieldsAddr,
500	                HstDescriptorFieldsSize);
501	
502	    ODBG(ODT_Mapping) << "Updating " << HstPtrSize << " bytes of descriptor ("
503	                      << TgtPtrAddr << ") (pointer + "
504	                      << HstDescriptorFieldsSize
505	                      << " additional bytes from host descriptor "
506	                      << HstDescriptorFieldsAddr << ")";
507	  }
508	
509	  // Submit the populated source buffer to device.
510	  int SubmitResult = Device.submitData(TgtPtrAddr, SrcBuffer, HstPtrSize,
511	                                       AsyncInfo, PtrTPR.getEntry());
512	  return HandleSubmitResult(SubmitResult);
513	}
