515	/// Internal function to do the mapping and transfer the data to the device
516	int targetDataBegin(ident_t *Loc, DeviceTy &Device, int32_t ArgNum,
517	                    void **ArgsBase, void **Args, int64_t *ArgSizes,
518	                    int64_t *ArgTypes, map_var_info_t *ArgNames,
519	                    void **ArgMappers, AsyncInfoTy &AsyncInfo,
520	                    StateInfoTy *StateInfo, bool FromMapper) {
521	  assert(StateInfo && "StateInfo must be available for targetDataBegin for "
522	                      "handling ATTACH and TO/TOFROM map-types.");
523	  // process each input.
524	  for (int32_t I = 0; I < ArgNum; ++I) {
525	    // Ignore private variables and arrays - there is no mapping for them.
526	    if ((ArgTypes[I] & OMP_TGT_MAPTYPE_LITERAL) ||
527	        (ArgTypes[I] & OMP_TGT_MAPTYPE_PRIVATE))
528	      continue;
529	    TIMESCOPE_WITH_DETAILS_AND_IDENT(
530	        "HostToDev", "Size=" + std::to_string(ArgSizes[I]) + "B", Loc);
531	    if (ArgMappers && ArgMappers[I]) {
532	      // Instead of executing the regular path of targetDataBegin, call the
533	      // targetDataMapper variant which will call targetDataBegin again
534	      // with new arguments.
535	      ODBG(ODT_Mapping) << "Calling targetDataMapper for the " << I
536	                        << "th argument";
537	
538	      map_var_info_t ArgName = (!ArgNames) ? nullptr : ArgNames[I];
539	      int Rc = targetDataMapper(Loc, Device, ArgsBase[I], Args[I], ArgSizes[I],
540	                                ArgTypes[I], ArgName, ArgMappers[I], AsyncInfo,
541	                                targetDataBegin, StateInfo);
542	
543	      if (Rc != OFFLOAD_SUCCESS) {
544	        REPORT() << "Call to targetDataBegin via targetDataMapper for custom "
545	                    "mapper failed";
546	        return OFFLOAD_FAIL;
547	      }
548	
549	      // Skip the rest of this function, continue to the next argument.
550	      continue;
551	    }
552	
553	    void *HstPtrBegin = Args[I];
554	    void *HstPtrBase = ArgsBase[I];
555	    int64_t DataSize = ArgSizes[I];
556	    map_var_info_t HstPtrName = (!ArgNames) ? nullptr : ArgNames[I];
557	
558	    // ATTACH map-types are supposed to be handled after all mapping for the
559	    // construct is done. Defer their processing.
560	    if (ArgTypes[I] & OMP_TGT_MAPTYPE_ATTACH) {
561	      const bool IsCorrespondingPointerInit =
562	          (ArgTypes[I] & OMP_TGT_MAPTYPE_PRIVATE);
563	      // We don't need to keep track of PRIVATE | ATTACH entries. They
564	      // represent corresponding-pointer-initialization, and are handled
565	      // similar to firstprivate (PRIVATE | TO) entries by
566	      // PrivateArgumentManager.
567	      if (!IsCorrespondingPointerInit)
568	        StateInfo->AttachEntries.emplace_back(
569	            /*PointerBase=*/HstPtrBase, /*PointeeBegin=*/HstPtrBegin,
570	            /*PointerSize=*/DataSize, /*MapType=*/ArgTypes[I],
571	            /*PointeeName=*/HstPtrName);
572	
573	      ODBG(ODT_Mapping) << "Deferring ATTACH map-type processing for argument "
574	                        << I;
575	      continue;
576	    }
577	
578	    // Adjust for proper alignment if this is a combined entry (for structs).
579	    // Look at the next argument - if that is MEMBER_OF this one, then this one
580	    // is a combined entry.
581	    int64_t TgtPadding = 0;
582	    const int NextI = I + 1;
583	    if (getParentIndex(ArgTypes[I]) < 0 && NextI < ArgNum &&
584	        getParentIndex(ArgTypes[NextI]) == I) {
585	      int64_t Alignment = getPartialStructRequiredAlignment(HstPtrBase);
586	      TgtPadding = (int64_t)HstPtrBegin % Alignment;
587	      if (TgtPadding) {
588	        ODBG(ODT_Mapping) << "Using a padding of " << TgtPadding
589	                          << " bytes for begin address " << HstPtrBegin;
590	      }
591	    }
592	
593	    // Address of pointer on the host and device, respectively.
594	    void *PointerHstPtrBegin, *PointerTgtPtrBegin;
595	    TargetPointerResultTy PointerTpr;
596	    bool IsHostPtr = false;
597	    bool IsImplicit = ArgTypes[I] & OMP_TGT_MAPTYPE_IMPLICIT;
598	    // Force the creation of a device side copy of the data when:
599	    // a close map modifier was associated with a map that contained a to.
600	    bool HasCloseModifier = ArgTypes[I] & OMP_TGT_MAPTYPE_CLOSE;
601	    bool HasPresentModifier = ArgTypes[I] & OMP_TGT_MAPTYPE_PRESENT;
602	    bool HasHoldModifier = ArgTypes[I] & OMP_TGT_MAPTYPE_OMPX_HOLD;
603	    // UpdateRef is based on MEMBER_OF instead of TARGET_PARAM because if we
604	    // have reached this point via __tgt_target_data_begin and not __tgt_target
605	    // then no argument is marked as TARGET_PARAM ("omp target data map" is not
606	    // associated with a target region, so there are no target parameters). This
607	    // may be considered a hack, we could revise the scheme in the future.
608	    bool UpdateRef = !(ArgTypes[I] & OMP_TGT_MAPTYPE_MEMBER_OF);
609	
610	    MappingInfoTy::HDTTMapAccessorTy HDTTMap =
611	        Device.getMappingInfo().HostDataToTargetMap.getExclusiveAccessor();
612	    if (ArgTypes[I] & OMP_TGT_MAPTYPE_PTR_AND_OBJ) {
613	      ODBG(ODT_Mapping) << "Has a pointer entry";
614	      // Base is address of pointer.
615	      //
616	      // Usually, the pointer is already allocated by this time.  For example:
617	      //
618	      //   #pragma omp target map(s.p[0:N])
619	      //
620	      // The map entry for s comes first, and the PTR_AND_OBJ entry comes
621	      // afterward, so the pointer is already allocated by the time the
622	      // PTR_AND_OBJ entry is handled below, and PointerTgtPtrBegin is thus
623	      // non-null.  However, "declare target link" can produce a PTR_AND_OBJ
624	      // entry for a global that might not already be allocated by the time the
625	      // PTR_AND_OBJ entry is handled below, and so the allocation might fail
626	      // when HasPresentModifier.
627	      PointerTpr = Device.getMappingInfo().getTargetPointer(
628	          HDTTMap, HstPtrBase, HstPtrBase, /*TgtPadding=*/0, sizeof(void *),
629	          /*HstPtrName=*/nullptr,
630	          /*HasFlagTo=*/false, /*HasFlagAlways=*/false, IsImplicit, UpdateRef,
631	          HasCloseModifier, HasPresentModifier, HasHoldModifier, AsyncInfo,
632	          /*OwnedTPR=*/nullptr, /*ReleaseHDTTMap=*/false);
633	      PointerTgtPtrBegin = PointerTpr.TargetPointer;
634	      IsHostPtr = PointerTpr.Flags.IsHostPointer;
635	      if (!PointerTgtPtrBegin) {
636	        REPORT() << "Call to getTargetPointer returned null pointer ("
637	                 << (HasPresentModifier ? "'present' map type modifier"
638	                                        : "device failure or illegal mapping")
639	                 << ")";
640	        return OFFLOAD_FAIL;
641	      }
642	
643	      // Track new allocation, for eventual use in attachment decision-making.
644	      if (PointerTpr.Flags.IsNewEntry && !IsHostPtr)
645	        StateInfo->NewAllocations[HstPtrBase] = sizeof(void *);
646	
647	      ODBG(ODT_Mapping) << "There are " << sizeof(void *)
648	                        << " bytes allocated at target address "
649	                        << PointerTgtPtrBegin << " - is"
650	                        << (PointerTpr.Flags.IsNewEntry ? "" : " not")
651	                        << " new";
652	      PointerHstPtrBegin = HstPtrBase;
653	      // modify current entry.
654	      HstPtrBase = *reinterpret_cast<void **>(HstPtrBase);
655	      // No need to update pointee ref count for the first element of the
656	      // subelement that comes from mapper.
657	      UpdateRef =
658	          (!FromMapper || I != 0); // subsequently update ref count of pointee
659	    }
660	
661	    const bool HasFlagTo = ArgTypes[I] & OMP_TGT_MAPTYPE_TO;
662	    const bool HasFlagAlways = ArgTypes[I] & OMP_TGT_MAPTYPE_ALWAYS;
663	    // Note that HDTTMap will be released in getTargetPointer.
664	    auto TPR = Device.getMappingInfo().getTargetPointer(
665	        HDTTMap, HstPtrBegin, HstPtrBase, TgtPadding, DataSize, HstPtrName,
666	        HasFlagTo, HasFlagAlways, IsImplicit, UpdateRef, HasCloseModifier,
667	        HasPresentModifier, HasHoldModifier, AsyncInfo, PointerTpr.getEntry(),
668	        /*ReleaseHDTTMap=*/true, StateInfo);
669	    void *TgtPtrBegin = TPR.TargetPointer;
670	    IsHostPtr = TPR.Flags.IsHostPointer;
671	    // If data_size==0, then the argument could be a zero-length pointer to
672	    // NULL, so getOrAlloc() returning NULL is not an error.
673	    if (!TgtPtrBegin && (DataSize || HasPresentModifier)) {
674	      REPORT() << "Call to getTargetPointer returned null pointer ("
675	               << (HasPresentModifier ? "'present' map type modifier"
676	                                      : "device failure or illegal mapping")
677	               << ").";
678	      return OFFLOAD_FAIL;
679	    } else if (TgtPtrBegin && HasPresentModifier &&
680	               StateInfo->wasNewlyAllocated(HstPtrBegin).has_value()) {
681	      // For "PRESENT" entries, we may have cases like the following:
682	      //   int *xp = &x[0];
683	      //   map(alloc: x[:]) map(present, alloc: xp[1])
684	      // The "PRESENT" entry may be encountered after a previous entry
685	      // allocated new storage for the pointer.
686	      // To catch such cases, we need to look at any existing allocations
687	      // and error out if we have any matching the pointer.
688	      MESSAGE("device mapping required by 'present' map type modifier does not "
689	              "exist for host address " DPxMOD " (%" PRId64 " bytes)\n",
690	              DPxPTR(HstPtrBegin), DataSize);
691	      REPORT() << "Pointer " << HstPtrBegin
692	               << " was not present on the device upon entry to the region.";
693	      return OFFLOAD_FAIL;
694	    }
695	
696	    // Track new allocation, for eventual use in attachment/to decision-making.
697	    if (TPR.Flags.IsNewEntry && !IsHostPtr && TgtPtrBegin)
698	      StateInfo->NewAllocations[HstPtrBegin] = DataSize;
699	
700	    ODBG(ODT_Mapping) << "There are " << DataSize
701	                      << " bytes allocated at target address " << TgtPtrBegin
702	                      << " - is" << (TPR.Flags.IsNewEntry ? "" : " not")
703	                      << " new";
704	
705	    if (ArgTypes[I] & OMP_TGT_MAPTYPE_RETURN_PARAM) {
706	      uintptr_t Delta = reinterpret_cast<uintptr_t>(HstPtrBegin) -
707	                        reinterpret_cast<uintptr_t>(HstPtrBase);
708	      void *TgtPtrBase;
709	      if (TgtPtrBegin) {
710	        // Lookup succeeded, return device pointer adjusted by delta
711	        TgtPtrBase = reinterpret_cast<void *>(
712	            reinterpret_cast<uintptr_t>(TgtPtrBegin) - Delta);
713	        ODBG(ODT_Mapping) << "Returning device pointer " << TgtPtrBase;
714	      } else {
715	        // Lookup failed. So we have to decide what to do based on the
716	        // requested fallback behavior.
717	        //
718	        // Treat "preserve" as the default fallback behavior, since as per
719	        // OpenMP 5.1, for use_device_ptr/addr, when there's no corresponding
720	        // device pointer to translate into, it's the user's responsibility to
721	        // ensure that the host address is device-accessible.
722	        //
723	        // OpenMP 5.1, sec 2.14.2, target data construct, p 188, l26-31:
724	        // If a list item that appears in a use_device_ptr clause ... does not
725	        // point to a mapped object, it must contain a valid device address for
726	        // the target device, and the list item references are instead converted
727	        // to references to a local device pointer that refers to this device
728	        // address.
729	        //
730	        // OpenMP 6.1's `fb_nullify` fallback behavior: when the FB_NULLIFY bit
731	        // is set by the compiler, e.g. for `use/need_device_ptr(fb_nullify)`),
732	        // return `nullptr - Delta` when lookup fails.
733	        if (ArgTypes[I] & OMP_TGT_MAPTYPE_FB_NULLIFY) {
734	          TgtPtrBase = reinterpret_cast<void *>(
735	              reinterpret_cast<uintptr_t>(nullptr) - Delta);
736	          ODBG(ODT_Mapping) << "Returning offsetted null pointer " << TgtPtrBase
737	                            << " as fallback (lookup failed)";
738	        } else {
739	          TgtPtrBase = reinterpret_cast<void *>(
740	              reinterpret_cast<uintptr_t>(HstPtrBegin) - Delta);
741	          ODBG(ODT_Mapping) << "Returning host pointer " << TgtPtrBase
742	                            << " as fallback (lookup failed)";
743	        }
744	      }
745	      ArgsBase[I] = TgtPtrBase;
746	    }
747	
748	    if (ArgTypes[I] & OMP_TGT_MAPTYPE_PTR_AND_OBJ && !IsHostPtr) {
749	      int Ret = performPointerAttachment(
750	          Device, AsyncInfo, reinterpret_cast<void **>(PointerHstPtrBegin),
751	          HstPtrBase, HstPtrBegin,
752	          reinterpret_cast<void **>(PointerTgtPtrBegin), TgtPtrBegin,
753	          sizeof(void *), PointerTpr);
754	      if (Ret != OFFLOAD_SUCCESS)
755	        return OFFLOAD_FAIL;
756	    }
757	
758	    // Check if variable can be used on the device:
759	    bool IsStructMember = ArgTypes[I] & OMP_TGT_MAPTYPE_MEMBER_OF;
760	    if (getInfoLevel() & OMP_INFOTYPE_EMPTY_MAPPING && ArgTypes[I] != 0 &&
761	        !IsStructMember && !IsImplicit && !TPR.isPresent() &&
762	        !TPR.isContained() && !TPR.isHostPointer())
763	      INFO(OMP_INFOTYPE_EMPTY_MAPPING, Device.DeviceID,
764	           "variable %s does not have a valid device counterpart\n",
765	           (HstPtrName) ? getNameFromMapping(HstPtrName).c_str() : "unknown");
766	  }
767	
768	  return OFFLOAD_SUCCESS;
769	}
