771	/// Process deferred ATTACH map entries collected during targetDataBegin.
772	///
773	/// From OpenMP's perspective, when mapping something that has a base pointer,
774	/// such as:
775	/// ```cpp
776	///   int *p;
777	///   #pragma omp enter target data map(to: p[10:20])
778	/// ```
779	///
780	/// a pointer-attachment between p and &p[10] should occur if both p and
781	/// p[10] are present on the device after doing all allocations for all maps
782	/// on the construct, and one of the following is true:
783	///
784	/// * The pointer p was newly allocated while handling the construct
785	/// * The pointee p[10:20] was newly allocated while handling the construct
786	/// * attach(always) map-type modifier was specified (OpenMP 6.1)
787	///
788	/// That's why we collect all attach entries and new memory allocations during
789	/// targetDataBegin, and use that information to make the decision of whether
790	/// to perform a pointer-attachment or not here, after maps have been handled.
791	///
792	/// Additionally, once we decide that a pointer-attachment should be performed,
793	/// we need to make sure that it happens after any previously submitted data
794	/// transfers have completed, to avoid the possibility of the pending transfers
795	/// clobbering the attachment. For example:
796	///
797	/// ```cpp
798	///   int *p = ...;
799	///   int **pp = &p;
800	///   map(to: pp[0], p[0])
801	/// ```
802	///
803	/// Which would be represented by:
804	/// ```
805	/// &pp[0], &pp[0], sizeof(pp[0]), TO (1)
806	/// &p[0], &p[0], sizeof(p[0]), TO    (2)
807	///
808	/// &pp, &pp[0], sizeof(pp), ATTACH   (3)
809	/// &p, &p[0], sizeof(p), ATTACH      (4)
810	/// ```
811	///
812	/// (4) and (1) are both trying to modify the device memory corresponding to
813	/// `&p`. So, if we decide that (4) should do an attachment, we also need to
814	/// ensure that (4) happens after (1) is complete.
815	///
816	/// For this purpose, we insert a data_fence before the first
817	/// pointer-attachment, (3), to ensure that all pending transfers finish first.
818	int processAttachEntries(DeviceTy &Device, StateInfoTy &StateInfo,
819	                         AsyncInfoTy &AsyncInfo) {
820	  // Report all tracked allocations from both main loop and ATTACH processing
821	  if (!StateInfo.NewAllocations.empty()) {
822	    ODBG_OS(ODT_Mapping, [&](llvm::raw_ostream &OS) {
823	      OS << "Tracked " << StateInfo.NewAllocations.size()
824	         << " total new allocations:";
825	      for (const auto &Alloc : StateInfo.NewAllocations) {
826	        OS << "  Host ptr: " << Alloc.first << ", Size: " << Alloc.second
827	           << " bytes";
828	      }
829	    });
830	  }
831	
832	  if (StateInfo.AttachEntries.empty())
833	    return OFFLOAD_SUCCESS;
834	
835	  ODBG(ODT_Mapping) << "Processing " << StateInfo.AttachEntries.size()
836	                    << " deferred ATTACH map entries";
837	
838	  bool TreatAttachAutoAsAlways = MappingConfig::get().TreatAttachAutoAsAlways;
839	  if (TreatAttachAutoAsAlways)
840	    ODBG(ODT_Mapping) << "Treating ATTACH(auto) as ATTACH(always) because "
841	                      << "LIBOMPTARGET_TREAT_ATTACH_AUTO_AS_ALWAYS is true";
842	
843	  int Ret = OFFLOAD_SUCCESS;
844	  bool IsFirstPointerAttachment = true;
845	  for (size_t EntryIdx = 0; EntryIdx < StateInfo.AttachEntries.size();
846	       ++EntryIdx) {
847	    const auto &AttachEntry = StateInfo.AttachEntries[EntryIdx];
848	
849	    void **HstPtr = reinterpret_cast<void **>(AttachEntry.PointerBase);
850	
851	    void *HstPteeBase = *HstPtr;
852	    void *HstPteeBegin = AttachEntry.PointeeBegin;
853	
854	    int64_t PtrSize = AttachEntry.PointerSize;
855	    int64_t MapType = AttachEntry.MapType;
856	
857	    ODBG(ODT_Mapping) << "Processing ATTACH entry " << EntryIdx
858	                      << ": HstPtr=" << HstPtr
859	                      << ", HstPteeBegin=" << HstPteeBegin
860	                      << ", PtrSize=" << PtrSize << ", MapType=0x"
861	                      << llvm::utohexstr(MapType);
862	
863	    bool IsAttachAlways =
864	        (MapType & OMP_TGT_MAPTYPE_ALWAYS) || TreatAttachAutoAsAlways;
865	
866	    // Lambda to check if a pointer was newly allocated
867	    auto WasNewlyAllocated = [&](void *Ptr, const char *PtrName) {
868	      bool WasNewlyAllocated = StateInfo.wasNewlyAllocated(Ptr).has_value();
869	      ODBG(ODT_Mapping) << "Attach " << PtrName << " " << Ptr
870	                        << " was newly allocated: "
871	                        << (WasNewlyAllocated ? "yes" : "no");
872	      return WasNewlyAllocated;
873	    };
874	
875	    // Only process ATTACH if either the pointee or the pointer was newly
876	    // allocated, or the ALWAYS flag is set.
877	    if (!IsAttachAlways && !WasNewlyAllocated(HstPteeBegin, "pointee") &&
878	        !WasNewlyAllocated(HstPtr, "pointer")) {
879	      ODBG(ODT_Mapping) << "Skipping ATTACH entry " << EntryIdx
880	                        << ": neither pointer nor pointee was newly "
881	                           "allocated and no ALWAYS flag";
882	      continue;
883	    }
884	
885	    // Lambda to perform target pointer lookup and validation
886	    auto LookupTargetPointer =
887	        [&](void *Ptr, int64_t Size,
888	            const char *PtrType) -> std::optional<TargetPointerResultTy> {
889	      // ATTACH map-type does not change ref-count, or do any allocation
890	      // We just need to do a lookup for the pointer/pointee.
891	      TargetPointerResultTy TPR = Device.getMappingInfo().getTgtPtrBegin(
892	          Ptr, Size, /*UpdateRefCount=*/false,
893	          /*UseHoldRefCount=*/false, /*MustContain=*/true);
894	
895	      ODBG(ODT_Mapping) << "Attach " << PtrType << " lookup - IsPresent="
896	                        << (TPR.isPresent() ? "yes" : "no") << ", IsHostPtr="
897	                        << (TPR.Flags.IsHostPointer ? "yes" : "no");
898	
899	      if (!TPR.isPresent()) {
900	        ODBG(ODT_Mapping) << "Skipping ATTACH entry " << EntryIdx << ": "
901	                          << PtrType << " not present on device";
902	        return std::nullopt;
903	      }
904	      if (TPR.Flags.IsHostPointer) {
905	        ODBG(ODT_Mapping) << "Skipping ATTACH entry " << EntryIdx
906	                          << ": device version of the " << PtrType
907	                          << " is a host pointer.";
908	        return std::nullopt;
909	      }
910	
911	      return TPR;
912	    };
913	
914	    // Get device version of the pointee (e.g., &p[10]) first, as we can
915	    // release its TPR after extracting the pointer value.
916	    void *TgtPteeBegin = [&]() -> void * {
917	      if (auto PteeTPROpt = LookupTargetPointer(HstPteeBegin, 0, "pointee"))
918	        return PteeTPROpt->TargetPointer;
919	      return nullptr;
920	    }();
921	
922	    if (!TgtPteeBegin)
923	      continue;
924	
925	    // Get device version of the pointer (e.g., &p) next. We need to keep its
926	    // TPR for use in shadow-pointer handling during pointer-attachment.
927	    auto PtrTPROpt = LookupTargetPointer(HstPtr, PtrSize, "pointer");
928	    if (!PtrTPROpt)
929	      continue;
930	    TargetPointerResultTy &PtrTPR = *PtrTPROpt;
931	    void **TgtPtrBase = reinterpret_cast<void **>(PtrTPR.TargetPointer);
932	
933	    // Insert a data-fence before the first pointer-attachment.
934	    if (IsFirstPointerAttachment) {
935	      IsFirstPointerAttachment = false;
936	      ODBG(ODT_Mapping)
937	          << "Inserting a data fence before the first pointer attachment.";
938	      Ret = Device.dataFence(AsyncInfo);
939	      if (Ret != OFFLOAD_SUCCESS) {
940	        REPORT() << "Failed to insert data fence.";
941	        return OFFLOAD_FAIL;
942	      }
943	    }
944	
945	    // Do the pointer-attachment, i.e. update the device pointer to point to
946	    // device pointee.
947	    Ret = performPointerAttachment(Device, AsyncInfo, HstPtr, HstPteeBase,
948	                                   HstPteeBegin, TgtPtrBase, TgtPteeBegin,
949	                                   PtrSize, PtrTPR);
950	    if (Ret != OFFLOAD_SUCCESS)
951	      return OFFLOAD_FAIL;
952	
953	    ODBG(ODT_Mapping) << "ATTACH entry " << EntryIdx
954	                      << " processed successfully";
955	  }
956	
957	  return OFFLOAD_SUCCESS;
958	}
