961	/// This structure contains information to deallocate a target pointer, aka.
962	/// used to fix up the shadow map and potentially delete the entry from the
963	/// mapping table via \p DeviceTy::deallocTgtPtr.
964	struct PostProcessingInfo {
965	  /// Host pointer used to look up into the map table
966	  void *HstPtrBegin;
967	
968	  /// Size of the data
969	  int64_t DataSize;
970	
971	  /// The mapping type (bitfield).
972	  int64_t ArgType;
973	
974	  /// The target pointer information.
975	  TargetPointerResultTy TPR;
976	
977	  PostProcessingInfo(void *HstPtr, int64_t Size, int64_t ArgType,
978	                     TargetPointerResultTy &&TPR)
979	      : HstPtrBegin(HstPtr), DataSize(Size), ArgType(ArgType),
980	        TPR(std::move(TPR)) {}
981	};
