985	/// Applies the necessary post-processing procedures to entries listed in \p
986	/// EntriesInfo after the execution of all device side operations from a target
987	/// data end. This includes the update of pointers at the host and removal of
988	/// device buffer when needed. It returns OFFLOAD_FAIL or OFFLOAD_SUCCESS
989	/// according to the successfulness of the operations.
990	[[nodiscard]] static int
991	postProcessingTargetDataEnd(DeviceTy *Device,
992	                            SmallVector<PostProcessingInfo> &EntriesInfo) {
993	  int Ret = OFFLOAD_SUCCESS;
994	
995	  for (auto &[HstPtrBegin, DataSize, ArgType, TPR] : EntriesInfo) {
996	    bool DelEntry = !TPR.isHostPointer();
997	
998	    // If the last element from the mapper (for end transfer args comes in
999	    // reverse order), do not remove the partial entry, the parent struct still
1000	    // exists.
1001	    if ((ArgType & OMP_TGT_MAPTYPE_MEMBER_OF) &&
1002	        !(ArgType & OMP_TGT_MAPTYPE_PTR_AND_OBJ)) {
1003	      DelEntry = false; // protect parent struct from being deallocated
1004	    }
1005	
1006	    // If we marked the entry to be deleted we need to verify no other
1007	    // thread reused it by now. If deletion is still supposed to happen by
1008	    // this thread LR will be set and exclusive access to the HDTT map
1009	    // will avoid another thread reusing the entry now. Note that we do
1010	    // not request (exclusive) access to the HDTT map if DelEntry is
1011	    // not set.
1012	    MappingInfoTy::HDTTMapAccessorTy HDTTMap =
1013	        Device->getMappingInfo().HostDataToTargetMap.getExclusiveAccessor();
1014	
1015	    // We cannot use a lock guard because we may end up delete the mutex.
1016	    // We also explicitly unlocked the entry after it was put in the EntriesInfo
1017	    // so it can be reused.
1018	    TPR.getEntry()->lock();
1019	    auto *Entry = TPR.getEntry();
1020	
1021	    const bool IsNotLastUser = Entry->decDataEndThreadCount() != 0;
1022	    if (DelEntry && (Entry->getTotalRefCount() != 0 || IsNotLastUser)) {
1023	      // The thread is not in charge of deletion anymore. Give up access
1024	      // to the HDTT map and unset the deletion flag.
1025	      HDTTMap.destroy();
1026	      DelEntry = false;
1027	    }
1028	
1029	    // If we copied back to the host a struct/array containing pointers, or
1030	    // Fortran descriptors (which are larger than a "void *"), we need to
1031	    // restore the original host pointer/descriptor values from their shadow
1032	    // copies. If the struct is going to be deallocated, remove any remaining
1033	    // shadow pointer entries for this struct.
1034	    const bool HasFrom = ArgType & OMP_TGT_MAPTYPE_FROM;
1035	    if (HasFrom) {
1036	      Entry->foreachShadowPointerInfo([&](const ShadowPtrInfoTy &ShadowPtr) {
1037	        constexpr int64_t VoidPtrSize = sizeof(void *);
1038	        if (ShadowPtr.PtrSize > VoidPtrSize) {
1039	          ODBG(ODT_Mapping)
1040	              << "Restoring host descriptor " << (void *)ShadowPtr.HstPtrAddr
1041	              << " to its original content (" << ShadowPtr.PtrSize
1042	              << " bytes), containing pointee address "
1043	              << (void *)ShadowPtr.HstPtrContent.data();
1044	        } else {
1045	          ODBG(ODT_Mapping)
1046	              << "Restoring host pointer " << (void *)ShadowPtr.HstPtrAddr
1047	              << " to its original value "
1048	              << (void *)ShadowPtr.HstPtrContent.data();
1049	        }
1050	        std::memcpy(ShadowPtr.HstPtrAddr, ShadowPtr.HstPtrContent.data(),
1051	                    ShadowPtr.PtrSize);
1052	        return OFFLOAD_SUCCESS;
1053	      });
1054	    }
1055	
1056	    // Give up the lock as we either don't need it anymore (e.g., done with
1057	    // TPR), or erase TPR.
1058	    TPR.setEntry(nullptr);
1059	
1060	    if (!DelEntry)
1061	      continue;
1062	
1063	    Ret = Device->getMappingInfo().eraseMapEntry(HDTTMap, Entry, DataSize);
1064	    // Entry is already remove from the map, we can unlock it now.
1065	    HDTTMap.destroy();
1066	    Ret |= Device->getMappingInfo().deallocTgtPtrAndEntry(Entry, DataSize);
1067	    if (Ret != OFFLOAD_SUCCESS) {
1068	      REPORT() << "Deallocating data from device failed.";
1069	      break;
1070	    }
1071	  }
1072	
1073	  delete &EntriesInfo;
1074	  return Ret;
1075	}
