1077	/// Internal function to undo the mapping and retrieve the data from the device.
1078	int targetDataEnd(ident_t *Loc, DeviceTy &Device, int32_t ArgNum,
1079	                  void **ArgBases, void **Args, int64_t *ArgSizes,
1080	                  int64_t *ArgTypes, map_var_info_t *ArgNames,
1081	                  void **ArgMappers, AsyncInfoTy &AsyncInfo,
1082	                  StateInfoTy *StateInfo, bool FromMapper) {
1083	  assert(StateInfo && "StateInfo is required for targetDataEnd for handling "
1084	                      "FROM data transfers");
1085	  int Ret = OFFLOAD_SUCCESS;
1086	  auto *PostProcessingPtrs = new SmallVector<PostProcessingInfo>();
1087	  // process each input.
1088	  for (int32_t I = ArgNum - 1; I >= 0; --I) {
1089	    // Ignore private variables and arrays - there is no mapping for them.
1090	    // Also, ignore the use_device_ptr directive, it has no effect here.
1091	    if ((ArgTypes[I] & OMP_TGT_MAPTYPE_LITERAL) ||
1092	        (ArgTypes[I] & OMP_TGT_MAPTYPE_PRIVATE))
1093	      continue;
1094	
1095	    // Ignore ATTACH entries - they should only be honored on map-entering
1096	    // directives. They may be encountered here while handling the "end" part of
1097	    // "#pragma omp target".
1098	    if (ArgTypes[I] & OMP_TGT_MAPTYPE_ATTACH) {
1099	      ODBG(ODT_Mapping) << "Ignoring ATTACH entry " << I << " in targetDataEnd";
1100	      continue;
1101	    }
1102	
1103	    if (ArgMappers && ArgMappers[I]) {
1104	      // Instead of executing the regular path of targetDataEnd, call the
1105	      // targetDataMapper variant which will call targetDataEnd again
1106	      // with new arguments.
1107	      ODBG(ODT_Mapping) << "Calling targetDataMapper for the " << I
1108	                        << "th argument";
1109	
1110	      map_var_info_t ArgName = (!ArgNames) ? nullptr : ArgNames[I];
1111	      Ret = targetDataMapper(Loc, Device, ArgBases[I], Args[I], ArgSizes[I],
1112	                             ArgTypes[I], ArgName, ArgMappers[I], AsyncInfo,
1113	                             targetDataEnd, StateInfo);
1114	
1115	      if (Ret != OFFLOAD_SUCCESS) {
1116	        REPORT() << "Call to targetDataEnd via targetDataMapper for custom "
1117	                    "mapper failed.";
1118	        return OFFLOAD_FAIL;
1119	      }
1120	
1121	      // Skip the rest of this function, continue to the next argument.
1122	      continue;
1123	    }
1124	
1125	    void *HstPtrBegin = Args[I];
1126	    int64_t DataSize = ArgSizes[I];
1127	    bool IsImplicit = ArgTypes[I] & OMP_TGT_MAPTYPE_IMPLICIT;
1128	    bool UpdateRef = !(ArgTypes[I] & OMP_TGT_MAPTYPE_MEMBER_OF) ||
1129	                     (ArgTypes[I] & OMP_TGT_MAPTYPE_PTR_AND_OBJ);
1130	    bool ForceDelete = ArgTypes[I] & OMP_TGT_MAPTYPE_DELETE;
1131	    bool HasPresentModifier = ArgTypes[I] & OMP_TGT_MAPTYPE_PRESENT;
1132	    bool HasHoldModifier = ArgTypes[I] & OMP_TGT_MAPTYPE_OMPX_HOLD;
1133	
1134	    // If PTR_AND_OBJ, HstPtrBegin is address of pointee
1135	    TargetPointerResultTy TPR = Device.getMappingInfo().getTgtPtrBegin(
1136	        HstPtrBegin, DataSize, UpdateRef, HasHoldModifier, !IsImplicit,
1137	        ForceDelete, /*FromDataEnd=*/true);
1138	    void *TgtPtrBegin = TPR.TargetPointer;
1139	    if (!TPR.isPresent() && !TPR.isHostPointer() &&
1140	        (DataSize || HasPresentModifier)) {
1141	      ODBG(ODT_Mapping) << "Mapping does not exist ("
1142	                        << (HasPresentModifier ? "'present' map type modifier"
1143	                                               : "ignored")
1144	                        << ")";
1145	      if (HasPresentModifier) {
1146	        // OpenMP 5.1, sec. 2.21.7.1 "map Clause", p. 350 L10-13:
1147	        // "If a map clause appears on a target, target data, target enter data
1148	        // or target exit data construct with a present map-type-modifier then
1149	        // on entry to the region if the corresponding list item does not appear
1150	        // in the device data environment then an error occurs and the program
1151	        // terminates."
1152	        //
1153	        // This should be an error upon entering an "omp target exit data".  It
1154	        // should not be an error upon exiting an "omp target data" or "omp
1155	        // target".  For "omp target data", Clang thus doesn't include present
1156	        // modifiers for end calls.  For "omp target", we have not found a valid
1157	        // OpenMP program for which the error matters: it appears that, if a
1158	        // program can guarantee that data is present at the beginning of an
1159	        // "omp target" region so that there's no error there, that data is also
1160	        // guaranteed to be present at the end.
1161	        MESSAGE("device mapping required by 'present' map type modifier does "
1162	                "not exist for host address " DPxMOD " (%" PRId64 " bytes)",
1163	                DPxPTR(HstPtrBegin), DataSize);
1164	        return OFFLOAD_FAIL;
1165	      }
1166	    } else {
1167	      ODBG(ODT_Mapping) << "There are " << DataSize
1168	                        << " bytes allocated at target address " << TgtPtrBegin
1169	                        << " - is" << (TPR.Flags.IsLast ? "" : " not")
1170	                        << " last";
1171	    }
1172	
1173	    // OpenMP 5.1, sec. 2.21.7.1 "map Clause", p. 351 L14-16:
1174	    // "If the map clause appears on a target, target data, or target exit data
1175	    // construct and a corresponding list item of the original list item is not
1176	    // present in the device data environment on exit from the region then the
1177	    // list item is ignored."
1178	    if (!TPR.isPresent())
1179	      continue;
1180	
1181	    // Track entries whose ref-count went to zero (IsLast=true) so that we
1182	    // can honor any subsequently encountered FROM entries that fall within
1183	    // their range.
1184	    if (TPR.Flags.IsLast) {
1185	      // For assumed-size arrays like map(delete: p[:]), the compiler provides
1186	      // no size information, so we need to get the actual allocated extent from
1187	      // the HDTT entry.
1188	      void *ReleasedHstPtrBegin =
1189	          reinterpret_cast<void *>(TPR.getEntry()->HstPtrBegin);
1190	      int64_t ReleasedSize =
1191	          TPR.getEntry()->HstPtrEnd - TPR.getEntry()->HstPtrBegin;
1192	      ODBG(ODT_Mapping) << "Tracking released entry: HstPtr="
1193	                        << ReleasedHstPtrBegin << ", Size=" << ReleasedSize
1194	                        << ", ForceDelete=" << ForceDelete;
1195	      StateInfo->ReleasedEntries[ReleasedHstPtrBegin] = ReleasedSize;
1196	    }
1197	
1198	    // Move data back to the host
1199	    const bool HasAlways = ArgTypes[I] & OMP_TGT_MAPTYPE_ALWAYS;
1200	    const bool HasFrom = ArgTypes[I] & OMP_TGT_MAPTYPE_FROM;
1201	
1202	    // Lambda to perform the actual FROM data retrieval from device to host
1203	    auto PerformFromRetrieval = [&](void *HstPtr, void *TgtPtr, int64_t Size,
1204	                                    HostDataToTargetTy *Entry) -> int {
1205	      // Check if this FROM transfer can be skipped.
1206	      //
1207	      // This is an optimization that may help in rare cases when we have
1208	      // multiple overlapping FROM entries. e.g.
1209	      //
1210	      // ... map(always, from: x) map(always, from: x)
1211	      // ... map(delete: x) map(from: x) map(from: x)
1212	      //
1213	      // If we think the overhead makes it not worh it, we can remove it.
1214	      if (auto TransferredEntry = StateInfo->wasTransferredFrom(HstPtr, Size)) {
1215	        void *TransferredPtr = TransferredEntry->first;
1216	        int64_t TransferredSize = TransferredEntry->second;
1217	        ODBG(ODT_Mapping) << "FROM entry HstPtr=" << HstPtr << " size=" << Size
1218	                          << " already transferred within [" << TransferredPtr
1219	                          << ", "
1220	                          << static_cast<void *>(
1221	                                 static_cast<char *>(TransferredPtr) +
1222	                                 TransferredSize)
1223	                          << ")";
1224	        return OFFLOAD_SUCCESS;
1225	      }
1226	
1227	      ODBG(ODT_Mapping) << "Moving " << Size << " bytes (tgt:" << TgtPtr
1228	                        << ") -> (hst:" << HstPtr << ")";
1229	      TIMESCOPE_WITH_DETAILS_AND_IDENT(
1230	          "DevToHost", "Size=" + std::to_string(Size) + "B", Loc);
1231	      // Wait for any previous transfer if an event is present.
1232	      if (void *Event = Entry->getEvent()) {
1233	        if (Device.waitEvent(Event, AsyncInfo) != OFFLOAD_SUCCESS) {
1234	          REPORT() << "Failed to wait for event " << Event << ".";
1235	          return OFFLOAD_FAIL;
1236	        }
1237	      }
1238	
1239	      int Ret = Device.retrieveData(HstPtr, TgtPtr, Size, AsyncInfo, Entry);
1240	      if (Ret != OFFLOAD_SUCCESS) {
1241	        REPORT() << "Copying data from device failed.";
1242	        return OFFLOAD_FAIL;
1243	      }
1244	
1245	      // As we are expecting to delete the entry the d2h copy might race
1246	      // with another one that also tries to delete the entry. This happens
1247	      // as the entry can be reused and the reuse might happen after the
1248	      // copy-back was issued but before it completed. Since the reuse might
1249	      // also copy-back a value we would race.
1250	      if (TPR.Flags.IsLast) {
1251	        if (Entry->addEventIfNecessary(Device, AsyncInfo) != OFFLOAD_SUCCESS)
1252	          return OFFLOAD_FAIL;
1253	      }
1254	
1255	      // Track this transfer to avoid duplicate transfers later on.
1256	      StateInfo->addTransferredFromEntry(HstPtr, Size);
1257	
1258	      return OFFLOAD_SUCCESS;
1259	    };
1260	
1261	    // Lambda to check if this pointer was previously released.
1262	    //
1263	    // This is needed to handle cases like the following:
1264	    //   p1 = p2 = &x;
1265	    //   ... map(delete: p1[:]) map(from: p2[0:1])
1266	    // The ref-count becomes zero before encountering the FROM entry, but we
1267	    // still need to do a transfer, if it went from non-zero to zero.
1268	    //
1269	    // OpenMP 6.0, sec. 7.9.6 "map Clause", p. 284 L24-26:
1270	    // If the reference count of the corresponding list item is one or if
1271	    // the always-modifier or delete-modifier is specified, and if the map
1272	    // type is from, the original list item is updated as if the list item
1273	    // appeared in a from clause on a target_update directive.
1274	    auto WasPreviouslyReleased = [&]() -> bool {
1275	      auto ReleasedEntry = StateInfo->wasPreviouslyReleased(HstPtrBegin);
1276	      if (!ReleasedEntry)
1277	        return false;
1278	
1279	      void *ReleasedPtr = ReleasedEntry->first;
1280	      int64_t ReleasedSize = ReleasedEntry->second;
1281	      ODBG(ODT_Mapping) << "Pointer HstPtr=" << HstPtrBegin
1282	                        << " falls within a range previously released ["
1283	                        << ReleasedPtr << ", "
1284	                        << static_cast<void *>(
1285	                               static_cast<char *>(ReleasedPtr) + ReleasedSize)
1286	                        << ") with size=" << ReleasedSize;
1287	      return true;
1288	    };
1289	
1290	    bool IsMapFromOnNonHostNonZeroData =
1291	        HasFrom && !TPR.Flags.IsHostPointer && DataSize != 0;
1292	
1293	    auto IsLastOrHasAlwaysOrWasReleased = [&]() {
1294	      return TPR.Flags.IsLast || HasAlways || WasPreviouslyReleased();
1295	    };
1296	
1297	    if (IsMapFromOnNonHostNonZeroData && IsLastOrHasAlwaysOrWasReleased()) {
1298	      Ret = PerformFromRetrieval(HstPtrBegin, TgtPtrBegin, DataSize,
1299	                                 TPR.getEntry());
1300	      if (Ret != OFFLOAD_SUCCESS)
1301	        return OFFLOAD_FAIL;
1302	    } else if (IsMapFromOnNonHostNonZeroData) {
1303	      // We can have cases like the following:
1304	      //   p1 = p2 = &x;
1305	      //  ... map(storage: p1[:]) map(from: p2[1:1])
1306	      //
1307	      // where it's possible that when the FROM entry is processed, the
1308	      // ref count is not zero, so no data transfer happens for it. But
1309	      // the ref-count can go down to zero once all maps have been processed
1310	      // for the current construct, in which case a transfer should happen.
1311	      //
1312	      // So, we keep track of any skipped FROM data-transfers, in case
1313	      // the ref-count goes down to zero later on.
1314	      //
1315	      // This cannot be handled in the compiler for all cases because the
1316	      // list-items may look very different, as shown in the example above,
1317	      // which is allowed with OpenMP 6.0:
1318	      //
1319	      // OpenMP 6.0, sec. 7.9.6 "map Clause", p. 286 L18-21:
1320	      // Two list items of the map clauses on the same construct must not share
1321	      // original storage unless one of the following is true: they are the same
1322	      // list item, one is the containing structure of the other, at least one
1323	      // is an assumed-size array, or at least one is implicitly mapped due to
1324	      // the list item also appearing in a use_device_addr clause.
1325	      StateInfo->addSkippedFromEntry(HstPtrBegin, DataSize);
1326	      ODBG(ODT_Mapping) << "Skipping FROM map transfer for HstPtr="
1327	                        << HstPtrBegin << " size=" << DataSize
1328	                        << " (IsLast=" << TPR.Flags.IsLast << ", TotalRefCount="
1329	                        << TPR.getEntry()->getTotalRefCount() << ")";
1330	    }
1331	
1332	    // If the ref-count went to zero (IsLast=true), check if any previously
1333	    // skipped FROM entries fall within this released entry's range.
1334	    if (TPR.Flags.IsLast && !StateInfo->SkippedFromEntries.empty()) {
1335	      uintptr_t ReleasedBeginPtrInt = TPR.getEntry()->HstPtrBegin;
1336	      uintptr_t ReleasedEndPtrInt = TPR.getEntry()->HstPtrEnd;
1337	      SmallVector<void *, 32> ToRemove;
1338	
1339	      for (auto &SkippedFromEntry : StateInfo->SkippedFromEntries) {
1340	        void *FromBeginPtr = SkippedFromEntry.first;
1341	        int64_t FromDataSize = SkippedFromEntry.second;
1342	        uintptr_t FromBeginPtrInt = reinterpret_cast<uintptr_t>(FromBeginPtr);
1343	
1344	        // Check if this skipped FROM entry's starting pointer falls within this
1345	        // released entry
1346	        if (FromBeginPtrInt >= ReleasedBeginPtrInt &&
1347	            FromBeginPtrInt < ReleasedEndPtrInt) {
1348	          ODBG(ODT_Mapping)
1349	              << "Found skipped FROM entry: HstPtr=" << FromBeginPtr
1350	              << " size=" << FromDataSize << " within region being released ["
1351	              << reinterpret_cast<void *>(ReleasedBeginPtrInt) << ", "
1352	              << reinterpret_cast<void *>(ReleasedEndPtrInt) << ")";
1353	
1354	          // Calculate offset within the target pointer
1355	          int64_t Offset = FromBeginPtrInt - ReleasedBeginPtrInt;
1356	          void *FromTgtBeginPtr =
1357	              static_cast<void *>(static_cast<char *>(TgtPtrBegin) + Offset);
1358	
1359	          // Perform the retrieval for this skipped entry
1360	          int Ret = PerformFromRetrieval(
1361	              reinterpret_cast<void *>(FromBeginPtrInt), FromTgtBeginPtr,
1362	              FromDataSize, TPR.getEntry());
1363	          if (Ret != OFFLOAD_SUCCESS)
1364	            return OFFLOAD_FAIL;
1365	
1366	          ToRemove.push_back(FromBeginPtr);
1367	        }
1368	      }
1369	
1370	      // Remove processed entries
1371	      for (void *Ptr : ToRemove)
1372	        StateInfo->SkippedFromEntries.erase(Ptr);
1373	    }
1374	
1375	    // Add pointer to the buffer for post-synchronize processing.
1376	    PostProcessingPtrs->emplace_back(HstPtrBegin, DataSize, ArgTypes[I],
1377	                                     std::move(TPR));
1378	    PostProcessingPtrs->back().TPR.getEntry()->unlock();
1379	  }
1380	
1381	  // Add post-processing functions
1382	  // TODO: We might want to remove `mutable` in the future by not changing the
1383	  // captured variables somehow.
1384	  AsyncInfo.addPostProcessingFunction([=, Device = &Device]() mutable -> int {
1385	    return postProcessingTargetDataEnd(Device, *PostProcessingPtrs);
1386	  });
1387	
1388	  return Ret;
1389	}
