1391	static int targetDataContiguous(ident_t *Loc, DeviceTy &Device, void *ArgsBase,
1392	                                void *HstPtrBegin, int64_t ArgSize,
1393	                                int64_t ArgType, AsyncInfoTy &AsyncInfo) {
1394	  TargetPointerResultTy TPR = Device.getMappingInfo().getTgtPtrBegin(
1395	      HstPtrBegin, ArgSize, /*UpdateRefCount=*/false,
1396	      /*UseHoldRefCount=*/false, /*MustContain=*/true);
1397	  void *TgtPtrBegin = TPR.TargetPointer;
1398	  if (!TPR.isPresent()) {
1399	    ODBG(ODT_Mapping) << "hst data:" << HstPtrBegin
1400	                      << " not found, becomes a noop";
1401	    if (ArgType & OMP_TGT_MAPTYPE_PRESENT) {
1402	      MESSAGE("device mapping required by 'present' motion modifier does not "
1403	              "exist for host address " DPxMOD " (%" PRId64 " bytes)",
1404	              DPxPTR(HstPtrBegin), ArgSize);
1405	      return OFFLOAD_FAIL;
1406	    }
1407	    return OFFLOAD_SUCCESS;
1408	  }
1409	
1410	  if (TPR.Flags.IsHostPointer) {
1411	    ODBG(ODT_Mapping) << "hst data:" << HstPtrBegin
1412	                      << " unified and shared, becomes a noop";
1413	    return OFFLOAD_SUCCESS;
1414	  }
1415	
1416	  if (ArgType & OMP_TGT_MAPTYPE_TO) {
1417	    ODBG(ODT_Mapping) << "Moving " << ArgSize << " bytes (hst:" << HstPtrBegin
1418	                      << ") -> (tgt:" << TgtPtrBegin << ")";
1419	    int Ret = Device.submitData(TgtPtrBegin, HstPtrBegin, ArgSize, AsyncInfo,
1420	                                TPR.getEntry());
1421	    if (Ret != OFFLOAD_SUCCESS) {
1422	      REPORT() << "Copying data to device failed.";
1423	      return OFFLOAD_FAIL;
1424	    }
1425	    if (TPR.getEntry()) {
1426	      int Ret = TPR.getEntry()->foreachShadowPointerInfo(
1427	          [&](ShadowPtrInfoTy &ShadowPtr) {
1428	            constexpr int64_t VoidPtrSize = sizeof(void *);
1429	            if (ShadowPtr.PtrSize > VoidPtrSize) {
1430	              ODBG(ODT_Mapping)
1431	                  << "Restoring target descriptor " << ShadowPtr.TgtPtrAddr
1432	                  << " to its original content (" << ShadowPtr.PtrSize
1433	                  << " bytes), containing pointee address "
1434	                  << static_cast<const void *>(ShadowPtr.TgtPtrContent.data());
1435	            } else {
1436	              ODBG(ODT_Mapping)
1437	                  << "Restoring target pointer " << ShadowPtr.TgtPtrAddr
1438	                  << " to its original value "
1439	                  << static_cast<const void *>(ShadowPtr.TgtPtrContent.data());
1440	            }
1441	            Ret = Device.submitData(ShadowPtr.TgtPtrAddr,
1442	                                    ShadowPtr.TgtPtrContent.data(),
1443	                                    ShadowPtr.PtrSize, AsyncInfo);
1444	            if (Ret != OFFLOAD_SUCCESS) {
1445	              REPORT() << "Copying data to device failed.";
1446	              return OFFLOAD_FAIL;
1447	            }
1448	            return OFFLOAD_SUCCESS;
1449	          });
1450	      if (Ret != OFFLOAD_SUCCESS) {
1451	        ODBG(ODT_Mapping) << "Updating shadow map failed";
1452	        return Ret;
1453	      }
1454	    }
1455	  }
1456	
1457	  if (ArgType & OMP_TGT_MAPTYPE_FROM) {
1458	    ODBG(ODT_Mapping) << "Moving " << ArgSize << " bytes (tgt:" << TgtPtrBegin
1459	                      << ") -> (hst:" << HstPtrBegin << ")";
1460	    int Ret = Device.retrieveData(HstPtrBegin, TgtPtrBegin, ArgSize, AsyncInfo,
1461	                                  TPR.getEntry());
1462	    if (Ret != OFFLOAD_SUCCESS) {
1463	      REPORT() << "Copying data from device failed.";
1464	      return OFFLOAD_FAIL;
1465	    }
1466	
1467	    // Wait for device-to-host memcopies for whole struct to complete,
1468	    // before restoring the correct host pointer/descriptor.
1469	    if (auto *Entry = TPR.getEntry()) {
1470	      AsyncInfo.addPostProcessingFunction([=]() -> int {
1471	        int Ret = Entry->foreachShadowPointerInfo(
1472	            [&](const ShadowPtrInfoTy &ShadowPtr) {
1473	              constexpr int64_t VoidPtrSize = sizeof(void *);
1474	              if (ShadowPtr.PtrSize > VoidPtrSize) {
1475	                ODBG(ODT_Mapping)
1476	                    << "Restoring host descriptor " << ShadowPtr.HstPtrAddr
1477	                    << " to its original content (" << ShadowPtr.PtrSize
1478	                    << " bytes), containing pointee address "
1479	                    << static_cast<const void *>(
1480	                           ShadowPtr.HstPtrContent.data());
1481	              } else {
1482	                ODBG(ODT_Mapping)
1483	                    << "Restoring host pointer " << ShadowPtr.HstPtrAddr
1484	                    << " to its original value "
1485	                    << static_cast<const void *>(
1486	                           ShadowPtr.HstPtrContent.data());
1487	              }
1488	              std::memcpy(ShadowPtr.HstPtrAddr, ShadowPtr.HstPtrContent.data(),
1489	                          ShadowPtr.PtrSize);
1490	              return OFFLOAD_SUCCESS;
1491	            });
1492	        Entry->unlock();
1493	        if (Ret != OFFLOAD_SUCCESS) {
1494	          ODBG(ODT_Mapping) << "Updating shadow map failed";
1495	          return Ret;
1496	        }
1497	        return OFFLOAD_SUCCESS;
1498	      });
1499	    }
1500	  }
1501	
1502	  return OFFLOAD_SUCCESS;
1503	}
