1505	static int targetDataNonContiguous(ident_t *Loc, DeviceTy &Device,
1506	                                   void *ArgsBase,
1507	                                   __tgt_target_non_contig *NonContig,
1508	                                   uint64_t Size, int64_t ArgType,
1509	                                   int CurrentDim, int DimSize, uint64_t Offset,
1510	                                   AsyncInfoTy &AsyncInfo) {
1511	  int Ret = OFFLOAD_SUCCESS;
1512	  if (CurrentDim < DimSize) {
1513	    for (unsigned int I = 0; I < NonContig[CurrentDim].Count; ++I) {
1514	      uint64_t CurOffset =
1515	          NonContig[CurrentDim].Offset + I * NonContig[CurrentDim].Stride;
1516	      // we only need to transfer the first element for the last dimension
1517	      // since we've already got a contiguous piece.
1518	      if (CurrentDim != DimSize - 1 || I == 0) {
1519	        Ret = targetDataNonContiguous(Loc, Device, ArgsBase, NonContig, Size,
1520	                                      ArgType, CurrentDim + 1, DimSize,
1521	                                      Offset + CurOffset, AsyncInfo);
1522	        // Stop the whole process if any contiguous piece returns anything
1523	        // other than OFFLOAD_SUCCESS.
1524	        if (Ret != OFFLOAD_SUCCESS)
1525	          return Ret;
1526	      }
1527	    }
1528	  } else {
1529	    void *Ptr = reinterpret_cast<void *>((char *)ArgsBase + Offset);
1530	    ODBG(ODT_Mapping) << "Transfer of non-contiguous : host ptr " << Ptr
1531	                      << " offset " << Offset << " len " << Size;
1532	    Ret = targetDataContiguous(Loc, Device, ArgsBase, Ptr, Size, ArgType,
1533	                               AsyncInfo);
1534	  }
1535	  return Ret;
1536	}
1537	
1538	static int getNonContigMergedDimension(__tgt_target_non_contig *NonContig,
1539	                                       int32_t DimSize) {
1540	  int RemovedDim = 0;
1541	  for (int I = DimSize - 1; I > 0; --I) {
1542	    if (NonContig[I].Count * NonContig[I].Stride == NonContig[I - 1].Stride)
1543	      RemovedDim++;
1544	  }
1545	  return RemovedDim;
1546	}
