1548	/// Internal function to pass data to/from the target.
1549	int targetDataUpdate(ident_t *Loc, DeviceTy &Device, int32_t ArgNum,
1550	                     void **ArgsBase, void **Args, int64_t *ArgSizes,
1551	                     int64_t *ArgTypes, map_var_info_t *ArgNames,
1552	                     void **ArgMappers, AsyncInfoTy &AsyncInfo,
1553	                     StateInfoTy *StateInfo, bool FromMapper) {
1554	  // process each input.
1555	  for (int32_t I = 0; I < ArgNum; ++I) {
1556	    if ((ArgTypes[I] & OMP_TGT_MAPTYPE_LITERAL) ||
1557	        (ArgTypes[I] & OMP_TGT_MAPTYPE_PRIVATE))
1558	      continue;
1559	
1560	    if (ArgMappers && ArgMappers[I]) {
1561	      // Instead of executing the regular path of targetDataUpdate, call the
1562	      // targetDataMapper variant which will call targetDataUpdate again
1563	      // with new arguments.
1564	      ODBG(ODT_Mapping) << "Calling targetDataMapper for the " << I
1565	                        << "th argument";
1566	      map_var_info_t ArgName = (!ArgNames) ? nullptr : ArgNames[I];
1567	      int Ret = targetDataMapper(Loc, Device, ArgsBase[I], Args[I], ArgSizes[I],
1568	                                 ArgTypes[I], ArgName, ArgMappers[I], AsyncInfo,
1569	                                 targetDataUpdate);
1570	
1571	      if (Ret != OFFLOAD_SUCCESS) {
1572	        REPORT() << "Call to targetDataUpdate via targetDataMapper for custom "
1573	                    "mapper failed.";
1574	        return OFFLOAD_FAIL;
1575	      }
1576	
1577	      // Skip the rest of this function, continue to the next argument.
1578	      continue;
1579	    }
1580	
1581	    int Ret = OFFLOAD_SUCCESS;
1582	
1583	    if (ArgTypes[I] & OMP_TGT_MAPTYPE_NON_CONTIG) {
1584	      __tgt_target_non_contig *NonContig = (__tgt_target_non_contig *)Args[I];
1585	      int32_t DimSize = ArgSizes[I];
1586	      ODBG(ODT_DataTransfer) << "Non contig descriptor:";
1587	      for (int I = 0; I < DimSize; I++)
1588	        ODBG(ODT_DataTransfer)
1589	            << "  Dim " << I << ": Offset " << NonContig[I].Offset << " Count "
1590	            << NonContig[I].Count << " Stride " << NonContig[I].Stride;
1591	      int32_t MergedDim = getNonContigMergedDimension(NonContig, DimSize);
1592	      ODBG(ODT_DataTransfer) << "Merged " << MergedDim << " dimensions";
1593	      __tgt_target_non_contig &FirstMergedDim =
1594	          NonContig[DimSize - MergedDim - 1];
1595	      uint64_t Size = FirstMergedDim.Count * FirstMergedDim.Stride;
1596	      ODBG(ODT_DataTransfer) << "Transfer size " << Size;
1597	      ODBG(ODT_DataTransfer) << "Base Ptr " << ArgsBase[I];
1598	      Ret = targetDataNonContiguous(
1599	          Loc, Device, ArgsBase[I], NonContig, Size, ArgTypes[I],
1600	          /*current_dim=*/0, DimSize - MergedDim, /*offset=*/0, AsyncInfo);
1601	    } else {
1602	      Ret = targetDataContiguous(Loc, Device, ArgsBase[I], Args[I], ArgSizes[I],
1603	                                 ArgTypes[I], AsyncInfo);
1604	    }
1605	    if (Ret == OFFLOAD_FAIL)
1606	      return OFFLOAD_FAIL;
1607	  }
1608	  return OFFLOAD_SUCCESS;
1609	}
