1611	static const unsigned LambdaMapping = OMP_TGT_MAPTYPE_PTR_AND_OBJ |
1612	                                      OMP_TGT_MAPTYPE_LITERAL |
1613	                                      OMP_TGT_MAPTYPE_IMPLICIT;
1614	static bool isLambdaMapping(int64_t Mapping) {
1615	  return (Mapping & LambdaMapping) == LambdaMapping;
