1619	/// Find the table information in the map or look it up in the translation
1620	/// tables.
1621	TableMap *getTableMap(void *HostPtr) {
1622	  std::lock_guard<std::mutex> TblMapLock(PM->TblMapMtx);
1623	  HostPtrToTableMapTy::iterator TableMapIt =
1624	      PM->HostPtrToTableMap.find(HostPtr);
1625	
1626	  if (TableMapIt != PM->HostPtrToTableMap.end())
1627	    return &TableMapIt->second;
1628	
1629	  // We don't have a map. So search all the registered libraries.
1630	  TableMap *TM = nullptr;
1631	  std::lock_guard<std::mutex> TrlTblLock(PM->TrlTblMtx);
1632	  for (HostEntriesBeginToTransTableTy::iterator Itr =
1633	           PM->HostEntriesBeginToTransTable.begin();
1634	       Itr != PM->HostEntriesBeginToTransTable.end(); ++Itr) {
1635	    // get the translation table (which contains all the good info).
1636	    TranslationTable *TransTable = &Itr->second;
1637	    // iterate over all the host table entries to see if we can locate the
1638	    // host_ptr.
1639	    llvm::offloading::EntryTy *Cur = TransTable->HostTable.EntriesBegin;
1640	    for (uint32_t I = 0; Cur < TransTable->HostTable.EntriesEnd; ++Cur, ++I) {
1641	      if (Cur->Address != HostPtr)
1642	        continue;
1643	      // we got a match, now fill the HostPtrToTableMap so that we
1644	      // may avoid this search next time.
1645	      TM = &(PM->HostPtrToTableMap)[HostPtr];
1646	      TM->Table = TransTable;
1647	      TM->Index = I;
1648	      return TM;
1649	    }
1650	  }
1651	
1652	  return nullptr;
1653	}
