1655	/// A class manages private arguments in a target region.
1656	class PrivateArgumentManagerTy {
1657	  /// A data structure for the information of first-private arguments. We can
1658	  /// use this information to optimize data transfer by packing all
1659	  /// first-private arguments and transfer them all at once.
1660	  struct FirstPrivateArgInfoTy {
1661	    /// Host pointer begin
1662	    char *HstPtrBegin;
1663	    /// Host pointer end
1664	    char *HstPtrEnd;
1665	    /// The index of the element in \p TgtArgs corresponding to the argument
1666	    int Index;
1667	    /// Alignment of the entry (base of the entry, not after the entry).
1668	    uint32_t Alignment;
1669	    /// Size (without alignment, see padding)
1670	    uint32_t Size;
1671	    /// Padding used to align this argument entry, if necessary.
1672	    uint32_t Padding;
1673	    /// Host pointer name
1674	    map_var_info_t HstPtrName = nullptr;
1675	    /// For corresponding-pointer-initialization: host pointee base address.
1676	    void *HstPteeBase = nullptr;
1677	    /// For corresponding-pointer-initialization: host pointee begin address.
1678	    void *HstPteeBegin = nullptr;
1679	    /// Whether this argument needs corresponding-pointer-initialization.
1680	    bool IsCorrespondingPointerInit = false;
1681	
1682	    FirstPrivateArgInfoTy(int Index, void *HstPtr, uint32_t Size,
1683	                          uint32_t Alignment, uint32_t Padding,
1684	                          map_var_info_t HstPtrName = nullptr,
1685	                          void *HstPteeBase = nullptr,
1686	                          void *HstPteeBegin = nullptr,
1687	                          bool IsCorrespondingPointerInit = false)
1688	        : HstPtrBegin(reinterpret_cast<char *>(HstPtr)),
1689	          HstPtrEnd(HstPtrBegin + Size), Index(Index), Alignment(Alignment),
1690	          Size(Size), Padding(Padding), HstPtrName(HstPtrName),
1691	          HstPteeBase(HstPteeBase), HstPteeBegin(HstPteeBegin),
1692	          IsCorrespondingPointerInit(IsCorrespondingPointerInit) {}
1693	  };
1694	
1695	  /// A vector of target pointers for all private arguments
1696	  SmallVector<void *> TgtPtrs;
1697	
1698	  /// A vector of information of all first-private arguments to be packed
1699	  SmallVector<FirstPrivateArgInfoTy> FirstPrivateArgInfo;
1700	  /// The total size of all arguments to be packed
1701	  int64_t FirstPrivateArgSize = 0;
1702	
1703	  /// A reference to the \p DeviceTy object
1704	  DeviceTy &Device;
1705	  /// A pointer to a \p AsyncInfoTy object
1706	  AsyncInfoTy &AsyncInfo;
1707	
1708	  /// \returns the value of the target pointee's base to be used for
1709	  /// corresponding-pointer-initialization.
1710	  void *getTargetPointeeBaseForCorrespondingPointerInitialization(
1711	      void *HstPteeBase, void *HstPteeBegin) {
1712	    // See if the pointee's begin address has corresponding storage on device.
1713	    void *TgtPteeBegin = [&]() -> void * {
1714	      if (!HstPteeBegin) {
1715	        ODBG(ODT_Mapping)
1716	            << "Corresponding-pointer-initialization: pointee begin address is "
1717	               "null";
1718	        return nullptr;
1719	      }
1720	
1721	      return Device.getMappingInfo()
1722	          .getTgtPtrBegin(HstPteeBegin, /*Size=*/0, /*UpdateRefCount=*/false,
1723	                          /*UseHoldRefCount=*/false)
1724	          .TargetPointer;
1725	    }();
1726	
1727	    // If it does, we calculate target pointee base using it, and return it.
1728	    // Otherwise, we retain the host pointee's base as the target pointee base
1729	    // of the initialized pointer. It's the user's responsibility to ensure
1730	    // that if a lookup fails, the host pointee is accessible on the device.
1731	    return TgtPteeBegin ? calculateTargetPointeeBase(HstPteeBase, HstPteeBegin,
1732	                                                     TgtPteeBegin)
1733	                        : HstPteeBase;
1734	  }
1735	
1736	  /// Initialize the source buffer for corresponding-pointer-initialization.
1737	  ///
1738	  /// It computes and stores the target pointee base address (or the host
1739	  /// pointee's base address, if lookup of target pointee fails) to the first
1740	  /// `sizeof(void*)` bytes of \p Buffer, and for larger pointers
1741	  /// (Fortran descriptors), the remaining fields of the host descriptor
1742	  /// \p HstPtr after those `sizeof(void*)` bytes.
1743	  ///
1744	  /// Corresponding-pointer-initialization represents the initialization of the
1745	  /// private version of a base-pointer/referring-pointer on a target construct.
1746	  ///
1747	  /// For example, for the following test:
1748	  /// ```cpp
1749	  ///   int x[10];
1750	  ///   int *px = &x[0];
1751	  ///   ...
1752	  ///   #pragma omp target data map(tofrom:px)
1753	  ///   {
1754	  ///     int **ppx = omp_get_mapped_ptr(&px, omp_get_default_device());
1755	  ///     #pragma omp target map(tofrom:px[1]) is_device_ptr(ppx)
1756	  ///     {
1757	  ///        foo(px, ppx);
1758	  ///     }
1759	  ///   }
1760	  /// ```
1761	  /// The following shows a possible way to implement the mapping of `px`,
1762	  /// which is pre-determined firstprivate and should get initialized
1763	  /// via corresponding-pointer-initialization:
1764	  ///
1765	  /// (A) Possible way to implement the above with PRIVATE | ATTACH:
1766	  /// ```llvm
1767	  ///  ; maps for px:
1768	  ///  ; &px[0], &px[1], sizeof(px[1]), TO | FROM                // (1)
1769	  ///  ; &px,    &px[1], sizeof(px),    ATTACH                   // (2)
1770	  ///  ; &px,    &px[1], sizeof(px),    PRIVATE | ATTACH | PARAM // (3)
1771	  ///  call... @__omp_outlined...(ptr %px, ptr %ppx)
1772	  ///  define ... @__omp_outlined(ptr %px, ptr %ppx) {...
1773	  ///    foo(%px, %ppx)
1774	  ///  ...}
1775	  /// ```
1776	  /// `(1)` maps the pointee `px[1].
1777	  /// `(2)` attaches it to the mapped version of `px`. It can be controlled by
1778	  /// the user based on the `attach(auto/always/never)` map-type modifier.
1779	  /// `(3)` privatizes and initializes the private pointer `px`, and passes it
1780	  /// into the kernel as the argument `%px`. Can be skipped if `px` is not
1781	  /// referenced in the target construct.
1782	  ///
1783	  /// While this method is not too beneficial compared to just doing the
1784	  /// initialization in the body of the kernel, like:
1785	  /// (B) Possible way to implement the above without PRIVATE | ATTACH:
1786	  /// ```llvm
1787	  ///  ; maps for px:
1788	  ///  ; &px[0], &px[1], sizeof(px[1]), TO | FROM | PARAM        // (4)
1789	  ///  ; &px,    &px[1], sizeof(px),    ATTACH                   // (5)
1790	  ///  call... @__omp_outlined...(ptr %px0, ptr %ppx)
1791	  ///  define ... __omp_outlined...(ptr %px0, ptr %ppx) {
1792	  ///    %px = alloca ptr;
1793	  ///    store ptr %px0, ptr %px
1794	  ///    foo(%px, %ppx)
1795	  ///  }
1796	  /// ```
1797	  ///
1798	  /// (B) is not so convenient for Fortran descriptors, because in
1799	  /// addition to the lookup, the remaining fields of the descriptor have
1800	  /// to be passed into the kernel to initialize the private copy, which
1801	  /// makes (A) a cleaner option for them. e.g.
1802	  /// ```f90
1803	  /// integer, pointer :: p(:)
1804	  /// !$omp target map(p(1))
1805	  /// ```
1806	  ///
1807	  /// (C) Possible mapping for the above Fortran test using PRIVATE | ATTACH:
1808	  /// ```llvm
1809	  ///  ; maps for p:
1810	  ///  ; &p(1),       &p(1), sizeof(p(1)),       TO | FROM
1811	  ///  ; &ref_ptr(p), &p(1), sizeof(ref_ptr(p)), ATTACH
1812	  ///  ; &ref_ptr(p), &p(1), sizeof(ref_ptr(p)), PRIVATE | ATTACH | PARAM
1813	  ///  call... @__omp_outlined...(ptr %ref_ptr_of_p)
1814	  void initBufferForCorrespondingPointerInitialization(char *Buffer,
1815	                                                       void *HstPtr,
1816	                                                       int64_t HstPtrSize,
1817	                                                       void *HstPteeBase,
1818	                                                       void *HstPteeBegin) {
1819	    constexpr int64_t VoidPtrSize = sizeof(void *);
1820	    assert(HstPtrSize >= VoidPtrSize &&
1821	           "corresponding-pointer-initialization: pointer size is too small");
1822	
1823	    void *TgtPteeBase =
1824	        getTargetPointeeBaseForCorrespondingPointerInitialization(HstPteeBase,
1825	                                                                  HstPteeBegin);
1826	
1827	    // Store the target pointee base address to the first VoidPtrSize bytes
1828	    ODBG(ODT_Mapping)
1829	        << "Corresponding-pointer-initialization: setting target pointee base "
1830	           "for "
1831	        << HstPtr << ", with pointee base " << TgtPteeBase;
1832	    std::memcpy(Buffer, &TgtPteeBase, VoidPtrSize);
1833	    if (HstPtrSize <= VoidPtrSize)
1834	      return;
1835	
1836	    // For Fortran descriptors, copy the remaining descriptor fields from host
1837	    uint64_t HstDescriptorFieldsSize = HstPtrSize - VoidPtrSize;
1838	    void *HstDescriptorFieldsAddr = static_cast<char *>(HstPtr) + VoidPtrSize;
1839	    ODBG(ODT_Mapping) << "Corresponding-pointer-initialization: copying "
1840	                      << HstDescriptorFieldsSize
1841	                      << " bytes of descriptor fields into buffer at offset "
1842	                      << VoidPtrSize << ", from " << HstDescriptorFieldsAddr;
1843	    std::memcpy(Buffer + VoidPtrSize, HstDescriptorFieldsAddr,
1844	                HstDescriptorFieldsSize);
1845	  }
1846	
1847	  /// Helper function to create and initialize a buffer to be used as the source
1848	  /// for corresponding-pointer-initialization.
1849	  void *createAndInitSourceBufferForCorrespondingPointerInitialization(
1850	      void *HstPtr, int64_t HstPtrSize, void *HstPteeBase, void *HstPteeBegin) {
1851	    char *Buffer = getOrCreateSourceBufferForSubmitData(AsyncInfo, HstPtrSize);
1852	    initBufferForCorrespondingPointerInitialization(Buffer, HstPtr, HstPtrSize,
1853	                                                    HstPteeBase, HstPteeBegin);
1854	    return Buffer;
1855	  }
1856	
1857	  // TODO: What would be the best value here? Should we make it configurable?
1858	  // If the size is larger than this threshold, we will allocate and transfer it
1859	  // immediately instead of packing it.
1860	  static constexpr const int64_t FirstPrivateArgSizeThreshold = 1024;
1861	
1862	public:
1863	  /// Constructor
1864	  PrivateArgumentManagerTy(DeviceTy &Dev, AsyncInfoTy &AsyncInfo)
1865	      : Device(Dev), AsyncInfo(AsyncInfo) {}
1866	
1867	  /// Add a private argument
1868	  int addArg(void *HstPtr, int64_t ArgSize, int64_t ArgOffset,
1869	             bool IsFirstPrivate, void *&TgtPtr, int TgtArgsIndex,
1870	             map_var_info_t HstPtrName = nullptr,
1871	             const bool AllocImmediately = false, void *HstPteeBase = nullptr,
1872	             void *HstPteeBegin = nullptr,
1873	             bool IsCorrespondingPointerInit = false) {
1874	    // If the argument is not first-private, or its size is greater than a
1875	    // predefined threshold, we will allocate memory and issue the transfer
1876	    // immediately.
1877	    if (ArgSize > FirstPrivateArgSizeThreshold || !IsFirstPrivate ||
1878	        AllocImmediately) {
1879	      TgtPtr = Device.allocData(ArgSize, HstPtr);
1880	      if (!TgtPtr) {
1881	        ODBG(ODT_Alloc) << "Data allocation for "
1882	                        << (IsFirstPrivate ? "first-" : "") << "private array "
1883	                        << HstPtr << " failed.";
1884	        return OFFLOAD_FAIL;
1885	      }
1886	
1887	      ODBG(ODT_Alloc) << "Allocated " << ArgSize
1888	                      << " bytes of target memory at " << TgtPtr << " for "
1889	                      << (IsFirstPrivate ? "first-" : "") << "private array "
1890	                      << HstPtr << " - pushing target argument "
1891	                      << (void *)((intptr_t)TgtPtr + ArgOffset);
1892	
1893	      // If first-private, copy data from host
1894	      if (IsFirstPrivate) {
1895	        ODBG(ODT_Mapping) << "Submitting firstprivate data to the device.";
1896	
1897	        // The source value used for corresponding-pointer-initialization
1898	        // is different vs regular firstprivates.
1899	        void *DataSource =
1900	            IsCorrespondingPointerInit
1901	                ? createAndInitSourceBufferForCorrespondingPointerInitialization(
1902	                      HstPtr, ArgSize, HstPteeBase, HstPteeBegin)
1903	                : HstPtr;
1904	        int Ret = Device.submitData(TgtPtr, DataSource, ArgSize, AsyncInfo);
1905	        if (Ret != OFFLOAD_SUCCESS) {
1906	          ODBG(ODT_Mapping) << "Copying "
1907	                            << (IsCorrespondingPointerInit
1908	                                    ? "corresponding-pointer-initialization"
1909	                                    : "firstprivate")
1910	                            << " data to device failed.";
1911	          return OFFLOAD_FAIL;
1912	        }
1913	      }
1914	      TgtPtrs.push_back(TgtPtr);
1915	    } else {
1916	      ODBG(ODT_Mapping) << "Firstprivate array " << HstPtr << " of size "
1917	                        << ArgSize << " will be packed";
1918	      // When reach this point, the argument must meet all following
1919	      // requirements:
1920	      // 1. Its size does not exceed the threshold (see the comment for
1921	      // FirstPrivateArgSizeThreshold);
1922	      // 2. It must be first-private (needs to be mapped to target device).
1923	      // We will pack all this kind of arguments to transfer them all at once
1924	      // to reduce the number of data transfer. We will not take
1925	      // non-first-private arguments, aka. private arguments that doesn't need
1926	      // to be mapped to target device, into account because data allocation
1927	      // can be very efficient with memory manager.
1928	
1929	      // Placeholder value
1930	      TgtPtr = nullptr;
1931	      auto *LastFPArgInfo =
1932	          FirstPrivateArgInfo.empty() ? nullptr : &FirstPrivateArgInfo.back();
1933	
1934	      // Compute the start alignment of this entry, add padding if necessary.
1935	      // TODO: Consider sorting instead.
1936	      uint32_t Padding = 0;
1937	      uint32_t StartAlignment =
1938	          LastFPArgInfo ? LastFPArgInfo->Alignment : MaxAlignment;
1939	      if (LastFPArgInfo) {
1940	        // Check if we keep the start alignment or if it is shrunk due to the
1941	        // size of the last element.
1942	        uint32_t Offset = LastFPArgInfo->Size % StartAlignment;
1943	        if (Offset)
1944	          StartAlignment = Offset;
1945	        // We only need as much alignment as the host pointer had (since we
1946	        // don't know the alignment information from the source we might end up
1947	        // overaligning accesses but not too much).
1948	        uint32_t RequiredAlignment =
1949	            llvm::bit_floor(getPartialStructRequiredAlignment(HstPtr));
1950	        if (RequiredAlignment > StartAlignment) {
1951	          Padding = RequiredAlignment - StartAlignment;
1952	          StartAlignment = RequiredAlignment;
1953	        }
1954	      }
1955	
1956	      FirstPrivateArgInfo.emplace_back(
1957	          TgtArgsIndex, HstPtr, ArgSize, StartAlignment, Padding, HstPtrName,
1958	          HstPteeBase, HstPteeBegin, IsCorrespondingPointerInit);
1959	
1960	      FirstPrivateArgSize += Padding + ArgSize;
1961	    }
1962	
1963	    return OFFLOAD_SUCCESS;
1964	  }
1965	
1966	  /// Pack first-private arguments, replace place holder pointers in \p TgtArgs,
1967	  /// and start the transfer.
1968	  int packAndTransfer(SmallVector<void *> &TgtArgs) {
1969	    if (!FirstPrivateArgInfo.empty()) {
1970	      assert(FirstPrivateArgSize != 0 &&
1971	             "FirstPrivateArgSize is 0 but FirstPrivateArgInfo is empty");
1972	      // The packed buffer is the host source of the asynchronous submitData
1973	      // below, so its lifetime must outlive this object rather than be tied to
1974	      // it.
1975	      char *FirstPrivateArgBuffer =
1976	          getOrCreateSourceBufferForSubmitData(AsyncInfo, FirstPrivateArgSize);
1977	      // Not strictly necessary: the loop below writes every entry, and the
1978	      // inter-entry padding gaps it skips are never read by the device. Zero
1979	      // them anyway to keep the transferred buffer deterministic, which makes
1980	      // dumps easier to read and avoids tripping memory sanitizers.
1981	      std::memset(FirstPrivateArgBuffer, 0, FirstPrivateArgSize);
1982	      auto *Itr = FirstPrivateArgBuffer;
1983	      // Copy all host data to this buffer
1984	      for (FirstPrivateArgInfoTy &Info : FirstPrivateArgInfo) {
1985	        // First pad the pointer as we (have to) pad it on the device too.
1986	        Itr = std::next(Itr, Info.Padding);
1987	
1988	        if (Info.IsCorrespondingPointerInit)
1989	          initBufferForCorrespondingPointerInitialization(
1990	              &*Itr, Info.HstPtrBegin, Info.Size, Info.HstPteeBase,
1991	              Info.HstPteeBegin);
1992	        else
1993	          std::copy(Info.HstPtrBegin, Info.HstPtrEnd, Itr);
1994	        Itr = std::next(Itr, Info.Size);
1995	      }
1996	      // Allocate target memory
1997	      void *TgtPtr =
1998	          Device.allocData(FirstPrivateArgSize, FirstPrivateArgBuffer);
1999	      if (TgtPtr == nullptr) {
2000	        ODBG(ODT_Alloc)
2001	            << "Failed to allocate target memory for private arguments.";
2002	        return OFFLOAD_FAIL;
2003	      }
2004	      TgtPtrs.push_back(TgtPtr);
2005	      ODBG(ODT_Alloc) << "Allocated " << FirstPrivateArgSize
2006	                      << " bytes of target memory at " << TgtPtr;
2007	      // Transfer data to target device
2008	      ODBG(ODT_DataTransfer)
2009	          << "Submitting packed firstprivate arguments from host buffer at "
2010	          << static_cast<void *>(FirstPrivateArgBuffer);
2011	      int Ret = Device.submitData(TgtPtr, FirstPrivateArgBuffer,
2012	                                  FirstPrivateArgSize, AsyncInfo);
2013	      if (Ret != OFFLOAD_SUCCESS) {
2014	        ODBG(ODT_DataTransfer) << "Failed to submit data of private arguments.";
2015	        return OFFLOAD_FAIL;
2016	      }
2017	      // Fill in all placeholder pointers
2018	      auto TP = reinterpret_cast<uintptr_t>(TgtPtr);
2019	      for (FirstPrivateArgInfoTy &Info : FirstPrivateArgInfo) {
2020	        void *&Ptr = TgtArgs[Info.Index];
2021	        assert(Ptr == nullptr && "Target pointer is already set by mistaken");
2022	        // Pad the device pointer to get the right alignment.
2023	        TP += Info.Padding;
2024	        Ptr = reinterpret_cast<void *>(TP);
2025	        TP += Info.Size;

