370	template <typename TargetAsyncInfoTy>
371	static inline int targetKernel(ident_t *Loc, int64_t DeviceId, int32_t NumTeams,
372	                               int32_t ThreadLimit, void *HostPtr,
373	                               KernelArgsTy *KernelArgs) {
374	  assert(PM && "Runtime not initialized");
375	  static_assert(std::is_convertible_v<TargetAsyncInfoTy &, AsyncInfoTy &>,
376	                "Target AsyncInfoTy must be convertible to AsyncInfoTy.");
377	  ODBG(ODT_Interface) << "Entering target region for device " << DeviceId
378	                      << " with entry point " << HostPtr;
379	
380	  if (checkDevice(DeviceId, Loc)) {
381	    ODBG(ODT_Interface) << "Not offloading to device " << DeviceId;
382	    return OMP_TGT_FAIL;
383	  }
384	
385	  bool IsTeams = NumTeams != -1;
386	  if (!IsTeams)
387	    KernelArgs->UserNumBlocks[0] = NumTeams = 1;
388	
389	  KernelArgsTy LocalKernelArgs;
390	  UpgradedArgBuffersTy UpgradedBufs;
391	  KernelArgs = upgradeKernelArgs(KernelArgs, LocalKernelArgs, UpgradedBufs,
392	                                 NumTeams, ThreadLimit);
393	
394	  TIMESCOPE_WITH_DETAILS_AND_IDENT(
395	      "Runtime: target exe",
396	      "NumTeams=" + std::to_string(NumTeams) +
397	          ";NumArgs=" + std::to_string(KernelArgs->NumArgs),
398	      Loc);
399	
400	  // The implicit dyn_ptr slot is always the last entry for versions that
401	  // support it.  Exclude it from user-facing info output.
402	  uint32_t UserArgCount = KernelArgs->NumArgs;
403	  if (KernelArgs->Version >= OMP_KERNEL_ARG_MIN_VERSION_WITH_DYN_PTR &&
404	      UserArgCount > 0)
405	    --UserArgCount;
406	
407	  if (getInfoLevel() & OMP_INFOTYPE_KERNEL_ARGS)
408	    printKernelArguments(Loc, DeviceId, UserArgCount, KernelArgs->ArgSizes,
409	                         KernelArgs->ArgTypes, KernelArgs->ArgNames,
410	                         "Entering OpenMP kernel");
411	
412	  ODBG_OS(ODT_Kernel, [&](llvm::raw_ostream &Os) {
413	    for (uint32_t I = 0; I < KernelArgs->NumArgs; ++I) {
414	      Os << "Entry" << llvm::format("%2d", I)
415	         << ": Base=" << KernelArgs->ArgBasePtrs[I]
416	         << ", Begin=" << KernelArgs->ArgPtrs[I]
417	         << ", Size=" << KernelArgs->ArgSizes[I]
418	         << ", Type=" << llvm::format("0x%" PRIx64, KernelArgs->ArgTypes[I])
419	         << ", Name="
420	         << (KernelArgs->ArgNames
421	                 ? getNameFromMapping(KernelArgs->ArgNames[I]).c_str()
422	                 : "unknown")
423	         << "\n";
424	    }
425	  });
426	
427	  auto DeviceOrErr = PM->getDevice(DeviceId);
428	  if (!DeviceOrErr)
429	    FATAL_MESSAGE(DeviceId, "%s", toString(DeviceOrErr.takeError()).c_str());
430	
431	  TargetAsyncInfoTy TargetAsyncInfo(*DeviceOrErr);
432	  AsyncInfoTy &AsyncInfo = TargetAsyncInfo;
433	  /// RAII to establish tool anchors before and after target region
434	  OMPT_IF_BUILT(InterfaceRAII TargetRAII(
435	                    RegionInterface.getCallbacks<ompt_target>(), DeviceId,
436	                    /*CodePtr=*/OMPT_GET_RETURN_ADDRESS);)
437	
438	  int Rc = OFFLOAD_SUCCESS;
439	  Rc = target(Loc, *DeviceOrErr, HostPtr, *KernelArgs, AsyncInfo);
440	  { // required to show synchronization
441	    TIMESCOPE_WITH_DETAILS_AND_IDENT("Runtime: synchronize", "", Loc);
442	    if (Rc == OFFLOAD_SUCCESS)
443	      Rc = AsyncInfo.synchronize();
444	
445	    handleTargetOutcome(Rc == OFFLOAD_SUCCESS, Loc);
446	    assert(Rc == OFFLOAD_SUCCESS && "__tgt_target_kernel unexpected failure!");
447	  }
448	  return OMP_TGT_SUCCESS;
449	}
450	
451	/// Implements a kernel entry that executes the target region on the specified
452	/// device.
453	///
454	/// \param Loc Source location associated with this target region.
455	/// \param DeviceId The device to execute this region, -1 indicated the default.
456	/// \param NumTeams Number of teams to launch the region with, -1 indicates a
457	///                 non-teams region and 0 indicates it was unspecified.
458	/// \param ThreadLimit Limit to the number of threads to use in the kernel
459	///                    launch, 0 indicates it was unspecified.
460	/// \param HostPtr  The pointer to the host function registered with the kernel.
461	/// \param Args     All arguments to this kernel launch (see struct definition).
462	EXTERN int __tgt_target_kernel(ident_t *Loc, int64_t DeviceId, int32_t NumTeams,
463	                               int32_t ThreadLimit, void *HostPtr,
464	                               KernelArgsTy *KernelArgs) {
465	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
466	  if (KernelArgs->Flags.NoWait)
467	    return targetKernel<TaskAsyncInfoWrapperTy>(
468	        Loc, DeviceId, NumTeams, ThreadLimit, HostPtr, KernelArgs);
469	  return targetKernel<AsyncInfoTy>(Loc, DeviceId, NumTeams, ThreadLimit,
470	                                   HostPtr, KernelArgs);
471	}
