480	///                   execution on persistent storage.
481	/// /param EmitReport Emit a summary report after the recording.
482	/// /param OutputDirPath The output directory where the record replay files
483	/// should be stored. An empty string or nullptr indicates the current working
484	/// directory should be used.
485	EXTERN int __tgt_activate_record_replay(int64_t DeviceId, uint64_t MemorySize,
486	                                        void *VAddr, bool IsRecord,
487	                                        bool SaveOutput, bool EmitReport,
488	                                        const char *OutputDirPath) {
