490	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
491	  auto DeviceOrErr = PM->getDevice(DeviceId);
492	  if (!DeviceOrErr)
493	    FATAL_MESSAGE(DeviceId, "%s", toString(DeviceOrErr.takeError()).c_str());
494	
495	  int Rc = target_activate_rr(*DeviceOrErr, MemorySize, VAddr, IsRecord,
496	                              SaveOutput, EmitReport, OutputDirPath);
497	  if (Rc != OFFLOAD_SUCCESS) {
