505	/// Implements a target kernel entry that replays a pre-recorded kernel.
506	/// \param Loc Source location associated with this target region (unused).
507	/// \param DeviceId The device identifier to execute the target region.
508	/// \param HostPtr A pointer to an address that uniquely identifies the kernel.
509	/// \param DeviceMemory A pointer to an array storing device memory data to move
510	///                     prior to kernel execution.
511	/// \param DeviceMemorySize The size of the above device memory data in bytes.
512	/// \param ReuseDeviceAlloc Pointer to a device memory allocation that should be
513	///                         reused for the replay. If null, the replay will
514	///                         allocate the necessary device buffer.
515	/// \param TgtArgs An array of pointers of the pre-recorded target kernel
516	///                arguments.
517	/// \param TgtOffsets An array of pointers of the pre-recorded target kernel
518	///                   argument offsets.
519	/// \param NumArgs The number of kernel arguments.
520	/// \param NumTeams Number of teams to launch the target region with.
521	/// \param ThreadLimit Limit to the number of threads to use in kernel
522	///                    execution.
523	/// \param LoopTripCount The pre-recorded value of the loop tripcount, if any.
524	/// \return OMP_TGT_SUCCESS on success, OMP_TGT_FAIL on failure.
525	EXTERN int __tgt_target_kernel_replay(
526	    ident_t *Loc, int64_t DeviceId, void *HostPtr, void *DeviceMemory,
527	    void *ReuseDeviceAlloc, int64_t DeviceMemorySize,
528	    const llvm::offloading::EntryTy *Globals, int32_t NumGlobals,
529	    void **TgtArgs, ptrdiff_t *TgtOffsets, int32_t NumArgs, int32_t NumTeams,
530	    int32_t ThreadLimit, uint32_t SharedMemorySize, uint64_t LoopTripCount,
531	    KernelReplayOutcomeTy *ReplayOutcome) {
532	  assert(PM && "Runtime not initialized");
533	  OMPT_IF_BUILT(ReturnAddressSetterRAII RA(__builtin_return_address(0)));
534	  if (checkDevice(DeviceId, Loc)) {
535	    ODBG(ODT_Interface) << "Not offloading to device " << DeviceId;
536	    return OMP_TGT_FAIL;
537	  }
538	  auto DeviceOrErr = PM->getDevice(DeviceId);
539	  if (!DeviceOrErr)
540	    FATAL_MESSAGE(DeviceId, "%s", toString(DeviceOrErr.takeError()).c_str());
541	
542	  /// RAII to establish tool anchors before and after target region
543	  OMPT_IF_BUILT(InterfaceRAII TargetRAII(
544	                    RegionInterface.getCallbacks<ompt_target>(), DeviceId,
545	                    /*CodePtr=*/OMPT_GET_RETURN_ADDRESS);)
546	
547	  AsyncInfoTy AsyncInfo(*DeviceOrErr);
548	  int Rc =
549	      target_replay(Loc, *DeviceOrErr, HostPtr, DeviceMemory, DeviceMemorySize,
550	                    ReuseDeviceAlloc, Globals, NumGlobals, TgtArgs, TgtOffsets,
551	                    NumArgs, NumTeams, ThreadLimit, SharedMemorySize,
552	                    LoopTripCount, AsyncInfo, ReplayOutcome);
553	
554	  if (Rc == OFFLOAD_SUCCESS)
555	    Rc = AsyncInfo.synchronize();
556	
557	  if (Rc != OFFLOAD_SUCCESS) {
558	    ODBG(ODT_Interface) << "Kernel replay failed in device " << DeviceId;
559	    return OMP_TGT_FAIL;
560	  }
561	  return OMP_TGT_SUCCESS;
562	}
