2409	int target_replay(ident_t *Loc, DeviceTy &Device, void *HostPtr,
2410	                  void *DeviceMemory, int64_t DeviceMemorySize,
2411	                  void *ReuseDeviceAlloc,
2412	                  const llvm::offloading::EntryTy *Globals, int32_t NumGlobals,
2413	                  void **TgtArgs, ptrdiff_t *TgtOffsets, int32_t NumArgs,
2414	                  int32_t NumTeams, int32_t ThreadLimit,
2415	                  uint32_t SharedMemorySize, uint64_t LoopTripCount,
2416	                  AsyncInfoTy &AsyncInfo,
2417	                  KernelReplayOutcomeTy *ReplayOutcome) {
2418	  int32_t DeviceId = Device.DeviceID;
2419	  int32_t NumSymbols = NumGlobals + 1;
2420	
2421	  struct SymbolDataTy {
2422	    void *DevPtr = nullptr;
2423	    TableMap *TM = nullptr;
2424	    __tgt_target_table *TargetTable = nullptr;
2425	  };
2426	  SmallVector<SymbolDataTy> Symbols(NumSymbols);
2427	
2428	  for (int32_t I = 0; I < NumSymbols; ++I) {
2429	    // The first symbol is the kernel entry.
2430	    void *SymbolHostPtr = (I == 0) ? HostPtr : Globals[I - 1].Address;
2431	
