2444	    for (auto &S : Symbols) {
2445	      assert(S.TM->Table->TargetsTable.size() > (size_t)DeviceId &&
2446	             "Not expecting a device ID outside the table's bounds!");
2447	      S.TargetTable = S.TM->Table->TargetsTable[DeviceId];
2448	      assert(S.TargetTable && "Global data has not been mapped\n");
2449	    }
2450	  }
