2452	  // Retrieve the device pointers for each symbol.
2453	  for (auto &S : Symbols)
2454	    S.DevPtr = S.TargetTable->EntriesBegin[S.TM->Index].Address;
2455	
2456	  // Initialize the device memory of each global.
2457	  for (int32_t I = 0; I < NumGlobals; ++I) {
